-- CMS only: private authoring and immutable publication snapshots.
create table public.hub_articles (
 id uuid primary key default gen_random_uuid(), guide_key text not null unique,
 draft jsonb not null, seed_context jsonb not null,
 published_revision_id bigint, edit_version bigint not null default 1,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.hub_article_revisions (
 id bigint generated always as identity primary key, article_id uuid not null references public.hub_articles(id),
 revision_number bigint not null check(revision_number > 0), content jsonb not null,
 state text not null default 'PUBLISHED' check(state = 'PUBLISHED'),
 action text not null check(action in ('IMPORT','PUBLISH','RESTORE')),
 actor uuid references auth.users(id), created_at timestamptz not null default now(),
 unique(article_id,revision_number)
);
alter table public.hub_articles add constraint hub_published_revision_fk foreign key(published_revision_id) references public.hub_article_revisions(id);
create unique index hub_draft_slug_unique on public.hub_articles ((draft->>'slug')) where draft->>'slug'<>'';
alter table public.hub_articles enable row level security;
alter table public.hub_article_revisions enable row level security;
revoke all on public.hub_articles,public.hub_article_revisions from public,anon,authenticated;
revoke all on sequence public.hub_article_revisions_id_seq from public,anon,authenticated;
grant select on public.hub_articles,public.hub_article_revisions to authenticated;
create policy hub_admin_read on public.hub_articles for select to authenticated using(exists(select 1 from public.admin_members where user_id=(select auth.uid())));
create policy hub_revision_admin_read on public.hub_article_revisions for select to authenticated using(exists(select 1 from public.admin_members where user_id=(select auth.uid())));
create view public.hub_article_library with (security_invoker=true) as select a.*,r.content as published_content from public.hub_articles a left join public.hub_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id;
revoke all on public.hub_article_library from public,anon,authenticated;
grant select on public.hub_article_library to authenticated;
create function public.hub_revision_immutable() returns trigger language plpgsql set search_path='' as $$begin raise exception 'CMS historical revisions are immutable' using errcode='42501';end$$;
create trigger hub_revision_no_change before update or delete on public.hub_article_revisions for each row execute function public.hub_revision_immutable();
revoke all on function public.hub_revision_immutable() from public,anon,authenticated;
create function public.hub_validate_node(n jsonb, refs jsonb, depth int default 0) returns void language plpgsql set search_path='' as $$
declare t text:=n->>'type';a jsonb:=coalesce(n->'attrs','{}');c jsonb;m jsonb;k text;
begin
 if depth>40 or jsonb_typeof(n)<>'object' or t is null or t not in ('doc','text','paragraph','heading','container','protected','protected_inline','bullet_list','ordered_list','list_item','callout','table','table_row','table_cell','table_header','hard_break') then raise exception 'Unsupported CMS body node' using errcode='23514';end if;
 for k in select jsonb_object_keys(n) loop if k not in ('type','attrs','text','content','marks') then raise exception 'Unexpected CMS body field' using errcode='23514';end if;end loop;
 if jsonb_typeof(a)<>'object' then raise exception 'Invalid CMS attributes' using errcode='23514';end if;
 for k in select jsonb_object_keys(a) loop if k not in ('ref','level','order','kind','colspan','rowspan','colwidth') then raise exception 'Unsafe CMS attribute' using errcode='23514';end if;end loop;
 if a ? 'ref' and (jsonb_typeof(a->'ref')<>'string' or not refs ? (a->>'ref')) then raise exception 'Unknown source reference' using errcode='23514';end if;
 if t in ('protected','protected_inline') and (not a ? 'ref' or refs->(a->>'ref')->>'kind'<>'protected') then raise exception 'Invalid preserved technical block' using errcode='23514';end if;
 if t='heading' and coalesce(a->>'level','') not in ('2','3') then raise exception 'Only H2/H3 permitted' using errcode='23514';end if;
 if a ? 'kind' and a->>'kind' not in ('note','warning') then raise exception 'Invalid callout' using errcode='23514';end if;
 if a ? 'order' and (jsonb_typeof(a->'order')<>'number' or (a->>'order')::int not between 1 and 1000) then raise exception 'Invalid list start' using errcode='23514';end if;
 if a ? 'colwidth' and a->'colwidth'<>'null'::jsonb then raise exception 'Column sizing is not an author control' using errcode='23514';end if;
 if t='text' and (jsonb_typeof(n->'text') is distinct from 'string' or length(n->>'text')=0) then raise exception 'Invalid body text' using errcode='23514';end if;
 if n ? 'text' and t<>'text' then raise exception 'Unexpected body text' using errcode='23514';end if;
 if n ? 'marks' then
  if jsonb_typeof(n->'marks')<>'array' then raise exception 'Invalid marks' using errcode='23514';end if;
  for m in select value from jsonb_array_elements(n->'marks') loop
   if coalesce(m->>'type','') not in ('strong','em','code','link') then raise exception 'Unsafe formatting' using errcode='23514';end if;
   for k in select jsonb_object_keys(m) loop if k not in ('type','attrs') then raise exception 'Unexpected formatting field' using errcode='23514';end if;end loop;
   for k in select jsonb_object_keys(coalesce(m->'attrs','{}')) loop if k<>'href' then raise exception 'Unsafe formatting attribute' using errcode='23514';end if;end loop;
   if m->>'type'='link' and (coalesce(m->'attrs'->>'href','') !~ '^(https://[^/@[:space:]\\]+([/?#].*)?|/([^/].*)?|#[A-Za-z0-9_-]+)$' or m->'attrs'->>'href' ~ '[[:space:]\\]') then raise exception 'Unsafe CMS link' using errcode='23514';end if;
  end loop;
 end if;
 if n ? 'content' then
  if jsonb_typeof(n->'content')<>'array' or jsonb_array_length(n->'content')>3000 then raise exception 'Invalid content array' using errcode='23514';end if;
  if t in ('text','protected','protected_inline','hard_break') then raise exception 'Leaf content cannot have children' using errcode='23514';end if;
  for c in select value from jsonb_array_elements(n->'content') loop
   if t in ('paragraph','heading') and c->>'type' not in ('text','hard_break','protected_inline') or t in ('bullet_list','ordered_list') and c->>'type'<>'list_item' or t='table' and c->>'type'<>'table_row' or t='table_row' and c->>'type' not in ('table_cell','table_header') or t in ('doc','container','list_item','callout','table_cell','table_header') and c->>'type' not in ('paragraph','heading','container','protected','bullet_list','ordered_list','callout','table') then raise exception 'Invalid CMS document structure' using errcode='23514';end if;
   perform public.hub_validate_node(c,refs,depth+1);
  end loop;
 end if;
end$$;
revoke all on function public.hub_validate_node(jsonb,jsonb,int) from public,anon,authenticated;
create function public.hub_validate_content(p jsonb,ctx jsonb,publishing boolean) returns void language plpgsql set search_path='' as $$
declare k text;v jsonb;s text;slots jsonb:=p->'body'->'slots';
begin
 if jsonb_typeof(p)<>'object' or octet_length(p::text)>1000000 then raise exception 'Invalid/oversized CMS article' using errcode='23514';end if;
 for k in select jsonb_object_keys(p) loop if k not in ('version','title','slug','category','intro','seo_title','meta_description','indexable','primary_intent','related','tools','components','published_at','content_updated_at','body') then raise exception 'Unexpected CMS intelligence field' using errcode='23514';end if;end loop;
 foreach k in array array['title','slug','intro','seo_title','meta_description'] loop
  if jsonb_typeof(p->k) is distinct from 'string' or length(p->>k)>(case k when 'slug' then 100 when 'intro' then 1000 when 'meta_description' then 600 else 200 end) or publishing and length(btrim(p->>k))=0 then raise exception 'Invalid required CMS field: %',k using errcode='23514';end if;
 end loop;
 s:=p->>'slug';if s<>'' and s!~'^[a-z0-9]+(-[a-z0-9]+)*$' or s in ('categories','index','hub-cms','search','admin','news') then raise exception 'Invalid/reserved CMS slug' using errcode='23514';end if;
 if coalesce(p->>'category','') not in ('potentiometers','tone-controls','treble-bleeds','wiring','pickups','troubleshooting') or jsonb_typeof(p->'indexable') is distinct from 'boolean' then raise exception 'Invalid category/indexability' using errcode='23514';end if;
 if coalesce(p->>'primary_intent','')<>coalesce(ctx->>'expected_intent','') then raise exception 'Discovery V2 primary nomination cannot be reassigned through CMS' using errcode='23514';end if;
 foreach k in array array['related','tools','components'] loop
  if jsonb_typeof(p->k) is distinct from 'array' or jsonb_array_length(p->k)>30 then raise exception 'Invalid CMS relationship' using errcode='23514';end if;
  for v in select value from jsonb_array_elements(p->k) loop
   if jsonb_typeof(v)<>'string' then raise exception 'Invalid relationship identity' using errcode='23514';end if;
   s:=v#>>'{}';if k='related' and not exists(select 1 from public.hub_articles a where a.guide_key=s and (not publishing or a.published_revision_id is not null)) or k='tools' and s not in ('signal','wiring','bleed') or k='components' and s not in ('potentiometers','capacitors','treble-bleeds','kits') then raise exception 'Unknown/private CMS relationship' using errcode='23514';end if;
  end loop;
 end loop;
 if p->'body'->>'version'<>'1' or jsonb_typeof(slots) is distinct from 'object' or (select array_agg(x order by x) from jsonb_object_keys(slots) x) is distinct from (select array_agg(x order by x) from jsonb_array_elements_text(ctx->'slots') x) then raise exception 'CMS presentation slot mismatch' using errcode='23514';end if;
 for v in select value from jsonb_each(slots) loop if v->>'type'<>'doc' or jsonb_typeof(v->'content') is distinct from 'array' or jsonb_array_length(v->'content')=0 then raise exception 'Body document required' using errcode='23514';end if;perform public.hub_validate_node(v,ctx->'refs');end loop;
 foreach k in array array['published_at','content_updated_at'] loop if p->>k is not null then if jsonb_typeof(p->k)<>'string' then raise exception 'Invalid CMS date' using errcode='23514';end if;perform (p->>k)::timestamptz;end if;end loop;
 if publishing and not exists(select 1 from jsonb_path_query(p->'body','lax $.**.text') as body_text(value) where length(btrim(body_text.value#>>'{}'))>0) then raise exception 'Article body cannot be empty' using errcode='23514';end if;
 if publishing and p->>'published_at' is not null and (p->>'published_at')::timestamptz>now() then raise exception 'CMS V2 publishes now; future dates remain drafts' using errcode='23514';end if;
end$$;
revoke all on function public.hub_validate_content(jsonb,jsonb,boolean) from public,anon,authenticated;
create function public.save_hub_article(p_id uuid,p_expected_version bigint,p_content jsonb,p_action text default 'DRAFT',p_restore_revision bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor_id uuid:=auth.uid();a public.hub_articles;c jsonb:=p_content;revision_id bigint;num bigint;
begin
 if actor_id is null or not exists(select 1 from public.admin_members where user_id=actor_id) then raise exception 'Admin membership required' using errcode='42501';end if;
 if p_action not in ('DRAFT','PUBLISH','RESTORE') then raise exception 'Unsupported CMS action' using errcode='23514';end if;
 if p_id is null then
  if p_action<>'DRAFT' then raise exception 'Create a draft before publication' using errcode='23514';end if;
  a.id:=gen_random_uuid();a.guide_key:='cms-'||a.id::text;a.seed_context:='{"template_key":"generic","expected_intent":null,"refs":{},"slots":["main"]}'::jsonb;
  perform public.hub_validate_content(c,a.seed_context,false);
  if c->>'slug'<>'' and exists(select 1 from public.hub_articles where draft->>'slug'=c->>'slug') then raise exception 'CMS slug collision' using errcode='23505';end if;
  insert into public.hub_articles(id,guide_key,draft,seed_context) values(a.id,a.guide_key,c,a.seed_context) returning * into a;return to_jsonb(a);
 end if;
 select * into a from public.hub_articles where id=p_id for update;if not found then raise exception 'CMS article missing' using errcode='23503';end if;
 if p_expected_version is distinct from a.edit_version then raise exception 'CMS article changed; reload before saving' using errcode='40001';end if;
 if p_action='RESTORE' then select content into c from public.hub_article_revisions where article_id=a.id and id=p_restore_revision;if not found then raise exception 'Revision does not belong to this article' using errcode='23503';end if;end if;
 perform public.hub_validate_content(c,a.seed_context,p_action<>'DRAFT');
 if a.published_revision_id is not null and c->>'slug'<>(select content->>'slug' from public.hub_article_revisions where id=a.published_revision_id) then raise exception 'Published CMS slug is immutable' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtext('hub-cms-slug:'||(c->>'slug')));
 if c->>'slug'<>'' and exists(select 1 from public.hub_articles other where other.id<>a.id and (other.draft->>'slug'=c->>'slug' or exists(select 1 from public.hub_article_revisions r where r.id=other.published_revision_id and r.content->>'slug'=c->>'slug'))) then raise exception 'CMS slug collision' using errcode='23505';end if;
 if p_action<>'DRAFT' then
  c:=jsonb_set(jsonb_set(c,'{published_at}',case when a.published_revision_id is not null then (select content->'published_at' from public.hub_article_revisions where id=a.published_revision_id) else coalesce(nullif(c->'published_at','null'::jsonb),to_jsonb(now())) end),'{content_updated_at}',to_jsonb(now()));
  select coalesce(max(revision_number),0)+1 into num from public.hub_article_revisions where article_id=a.id;
  insert into public.hub_article_revisions(article_id,revision_number,content,action,actor) values(a.id,num,c,p_action,actor_id) returning id into revision_id;
 end if;
 update public.hub_articles set draft=c,published_revision_id=coalesce(revision_id,published_revision_id),edit_version=edit_version+1,updated_at=now() where id=a.id returning * into a;
 return to_jsonb(a);
end$$;
revoke all on function public.save_hub_article(uuid,bigint,jsonb,text,bigint) from public,anon,authenticated;
grant execute on function public.save_hub_article(uuid,bigint,jsonb,text,bigint) to authenticated;
-- Deliberately public, allowlisted current published content; no draft/history/actor.
create function public.public_hub_articles() returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'guide_key',a.guide_key,'template_key',a.seed_context->>'template_key','content',r.content) order by a.guide_key),'[]'::jsonb)
 from public.hub_articles a join public.hub_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
$$;
revoke all on function public.public_hub_articles() from public,anon,authenticated;
grant execute on function public.public_hub_articles() to anon,authenticated;

-- Deterministic migration of existing published content only; no test articles.
insert into public.hub_articles(id,guide_key,draft,seed_context) values
('450eb708-4716-52ea-aa76-87fc0bb64b00','pots','{"version":1,"title":"Potentiometers Explained","slug":"potentiometers-explained","category":"potentiometers","intro":"The potentiometer is one of the simplest components inside an electric guitar, but it has a significant influence on how the controls behave and how the pickups interact with the rest of the circuit. Understanding a few basic specifications makes choosing the right pot considerably easier.","seo_title":"Guitar Potentiometers Explained","meta_description":"What resistance, taper and loading mean in a passive guitar, and how to choose a control that fits both the circuit and the instrument.","indexable":true,"primary_intent":"pots","related":["values","taper","lugs","lp-controls"],"tools":["signal","wiring"],"components":["potentiometers"],"published_at":null,"content_updated_at":"2026-10-04","body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"What is a potentiometer?"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"A potentiometer is a variable resistor with three electrical terminals. A movable contact, the wiper, travels along a resistive track as you turn the shaft. The resistance between the two outer track terminals stays approximately constant; resistance from the wiper to either end changes."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"In a passive guitar it commonly works as a volume control or as part of a tone control. These jobs use the same basic component in different connections."}]},{"type":"protected","attrs":{"ref":"r5"}},{"type":"paragraph","attrs":{"ref":"r6"},"content":[{"type":"text","text":"Our drawings show the rear of the potentiometer with its lugs pointing down. From left to right they are "},{"type":"text","text":"3, 2, 1","marks":[{"type":"strong"}]},{"type":"text","text":": lug 3 is the clockwise end, lug 2 is the wiper, and lug 1 is the anticlockwise end. The metal casing is a separate connection, not automatically connected to a track terminal. Verify orientation on the actual part."}]}]},{"type":"container","attrs":{"ref":"r7"},"content":[{"type":"heading","attrs":{"ref":"r8","level":2},"content":[{"type":"text","text":"Pot resistance"}]},{"type":"paragraph","attrs":{"ref":"r9"},"content":[{"type":"text","text":"The resistance printed on a potentiometer describes its full track. Common guitar values are 250kΩ, 500kΩ and 1MΩ (1,000kΩ). A volume pot forms part of the electrical load on a passive pickup, together with the tone network, cable and amplifier input."}]},{"type":"container","attrs":{"ref":"r10"},"content":[{"type":"protected","attrs":{"ref":"r11"}}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"Lower resistance generally loads a passive pickup more heavily and damps its resonant peak more; higher resistance loads it less. These are useful conventions, not rules about which pickup is allowed with which pot. The complete circuit and the player’s preference matter. Active electronics may require very different values; follow their manufacturer’s instructions."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"Audio vs linear taper"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"Taper describes how resistance changes with shaft rotation. A linear taper changes approximately in proportion to rotation. Audio or logarithmic taper changes at a different rate over the sweep, helping a volume control give a useful perceived progression."}]},{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"Audio taper is common for guitar volume, but neither taper is universally correct. A player who rides the volume may prefer a different response from someone who mainly switches between zero and full. Tone-control preferences vary too. Audio tapers also differ between manufacturers; an “A” or “B” marking should be checked against the maker’s convention."}]}]},{"type":"container","attrs":{"ref":"r17"},"content":[{"type":"heading","attrs":{"ref":"r18","level":2},"content":[{"type":"text","text":"Tolerance and Precision Matched"}]},{"type":"paragraph","attrs":{"ref":"r19"},"content":[{"type":"text","text":"A pot marked 500kΩ will rarely measure exactly 500.0kΩ. Manufacturing tolerance permits variation around that nominal value. Measure the outer track terminals with the component isolated from parallel circuit paths; an in-circuit reading can include other resistances."}]},{"type":"paragraph","attrs":{"ref":"r20"},"content":[{"type":"text","text":"Apparition individually electrically checks potentiometers. "},{"type":"text","text":"Precision Matched","marks":[{"type":"strong"}]},{"type":"text","text":" means selecting the closest practical group from available measured stock. It does not alter the resistive track or promise an arbitrary ±1% tolerance. The achievable match depends on the stock available when the kit is assembled."}]},{"type":"paragraph","attrs":{"ref":"r21"},"content":[{"type":"text","text":"Resistance matching does not mean two pots have identical taper, friction or mechanical dimensions. Those are separate specifications."}]}]},{"type":"container","attrs":{"ref":"r22"},"content":[{"type":"heading","attrs":{"ref":"r23","level":2},"content":[{"type":"text","text":"Shaft type and dimensions"}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"Short and long shaft usually describe mounting-bushing options, but sellers’ terminology varies. Measure the threaded bushing, the top/control-plate thickness and the space needed for washers and nuts. Do not choose from the guitar’s name alone."}]},{"type":"paragraph","attrs":{"ref":"r25"},"content":[{"type":"text","text":"A split shaft commonly accepts a push-on knob; a solid shaft commonly uses a grub-screw knob. Spline count, diameter and knob fit must agree. Metric and imperial bushings, threads and shaft sizes are not automatically interchangeable. Cavity depth, body diameter and push/pull clearance also matter."}]},{"type":"paragraph","attrs":{"ref":"r26"},"content":[{"type":"text","text":"Never force a knob onto an incompatible shaft or pull a pot through the guitar top by overtightening its nut. If the hole needs enlarging, get suitable workshop advice before modifying the instrument."}]}]},{"type":"container","attrs":{"ref":"r27"},"content":[{"type":"heading","attrs":{"ref":"r28","level":2},"content":[{"type":"text","text":"Volume controls"}]},{"type":"paragraph","attrs":{"ref":"r29"},"content":[{"type":"text","text":"In the standard circuit shown here, pickup hot reaches lug 3, lug 1 goes to common ground, and lug 2 sends a variable output onwards. The wiper divides the signal between input and ground. At full volume it approaches the input end; at zero it approaches ground."}]},{"type":"paragraph","attrs":{"ref":"r30"},"content":[{"type":"text","text":"Open in Wiring Diagram Generator →","marks":[{"type":"link","attrs":{"href":"/wiring-generator/?g=%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%7D"}}]}]}]},{"type":"container","attrs":{"ref":"r31"},"content":[{"type":"heading","attrs":{"ref":"r32","level":2},"content":[{"type":"text","text":"Tone controls"}]},{"type":"paragraph","attrs":{"ref":"r33"},"content":[{"type":"text","text":"A tone control uses part of the pot’s track with a capacitor to provide a variable, frequency-dependent path to ground. Turning it down reduces resistance in that branch. The capacitor value and the rest of the circuit determine the resulting response."}]},{"type":"paragraph","attrs":{"ref":"r34"},"content":[{"type":"text","text":"Read Capacitors and Treble Bleeds Explained →","marks":[{"type":"link","attrs":{"href":"/luthier-hub/capacitors-treble-bleeds/"}}]}]},{"type":"protected","attrs":{"ref":"r35"}}]},{"type":"container","attrs":{"ref":"r36"},"content":[{"type":"heading","attrs":{"ref":"r37","level":2},"content":[{"type":"text","text":"250 kΩ, 300 kΩ, 500 kΩ and 1 MΩ"}]},{"type":"paragraph","attrs":{"ref":"r38"},"content":[{"type":"text","text":"These nominal values are supported comparison assumptions in Signal Lab. A larger resistance generally presents less resistive loading, but the complete pickup, control and cable circuit determines the voltage response. Measured resistance can differ from nominal because of tolerance; brand alone does not define a tone. Audio/log and linear taper describe the track law, not its maximum resistance. Short or long threaded shafts, split or solid shafts and knob compatibility are physical fit decisions; measure the mounting thickness and clearance."}]}]},{"type":"protected","attrs":{"ref":"r39"}}]},"further":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r40"},"content":[{"type":"heading","attrs":{"ref":"r41","level":3},"content":[{"type":"text","text":"A resistor with a movable contact"}]},{"type":"paragraph","attrs":{"ref":"r42"},"content":[{"type":"text","text":"A potentiometer has a resistive track with a terminal at each end and a movable contact called the wiper. Turning the shaft moves that contact along the track. The resistance between the two end terminals is approximately the nominal value printed on the part; the resistances from the wiper to each end change as you turn it. Those are different measurements, and they answer different questions."}]},{"type":"paragraph","attrs":{"ref":"r43"},"content":[{"type":"text","text":"A passive guitar control does not add gain. It changes how the pickup and the rest of the circuit interact. Used as a volume control, a pot divides the signal between its input, wiper and ground. Used in a conventional tone branch, it varies the resistance associated with a capacitor. The same type of component can therefore serve two jobs without the two circuits working in the same way."}]}]},{"type":"container","attrs":{"ref":"r44"},"content":[{"type":"heading","attrs":{"ref":"r45","level":3},"content":[{"type":"text","text":"Resistance and pickup loading"}]},{"type":"paragraph","attrs":{"ref":"r46"},"content":[{"type":"text","text":"The pickup is not an ideal voltage source. Its resistance and inductance interact with control resistance, cable capacitance and the amplifier input. Even at full volume, the track between input and ground remains a load in the conventional volume circuit. A lower resistance generally damps the pickup’s electrical resonance more strongly; a higher resistance generally loads it less. This is a circuit relationship, not a promise that one value will sound better."}]},{"type":"paragraph","attrs":{"ref":"r47"},"content":[{"type":"text","text":"The tone branch and other connected controls can contribute additional loading. Replacing a 250 kΩ volume pot with a 500 kΩ part changes one element of that network, not every element. Compare values with the same pickup, cable and control positions. An active pickup or buffered circuit may call for quite different values, so follow its maker’s instructions."}]}]},{"type":"container","attrs":{"ref":"r48"},"content":[{"type":"heading","attrs":{"ref":"r49","level":3},"content":[{"type":"text","text":"Common values are starting points"}]},{"type":"container","attrs":{"ref":"r50"},"content":[{"type":"protected","attrs":{"ref":"r51"}}]},{"type":"paragraph","attrs":{"ref":"r52"},"content":[{"type":"text","text":"These conventions are not wiring rules. A mixed-pickup guitar, a particular resonant response or an existing harness can justify another choice. Tolerance also matters: two parts with the same printed value may measure differently. Record the actual resistance when repeatability matters instead of assuming that the label is an exact measurement."}]}]},{"type":"container","attrs":{"ref":"r53"},"content":[{"type":"heading","attrs":{"ref":"r54","level":3},"content":[{"type":"text","text":"Volume terminals: identify the function"}]},{"type":"container","attrs":{"ref":"r55"},"content":[{"type":"protected","attrs":{"ref":"r56"}}]},{"type":"paragraph","attrs":{"ref":"r57"},"content":[{"type":"text","text":"The simple path is pickup/selector → volume lug 3 → wiper/lug 2 → output jack TIP. Jack sleeve belongs to the return/ground network. A conventional Modern tone branch loads the signal-input node through the tone network toward ground; it is not an inline capacitor between the volume output and the jack."}]},{"type":"container","attrs":{"ref":"r58"},"content":[{"type":"heading","attrs":{"ref":"r59","level":3},"content":[{"type":"text","text":"Do not number by a photograph alone"}]},{"type":"paragraph","attrs":{"ref":"r60"},"content":[{"type":"text","text":"Front and rear views reverse apparent left and right. Verify the wiper and end terminals against the part drawing and a resistance measurement before transferring a lug number to a real component."}]}]}]},{"type":"container","attrs":{"ref":"r61"},"content":[{"type":"heading","attrs":{"ref":"r62","level":3},"content":[{"type":"text","text":"Taper is a separate specification"}]},{"type":"paragraph","attrs":{"ref":"r63"},"content":[{"type":"text","text":"Nominal resistance describes the full track. Taper describes how wiper resistance changes with rotation. An audio/logarithmic taper concentrates different proportions of the change into different parts of the travel; a linear taper changes track resistance approximately in proportion to rotation. Neither label guarantees a particular in-circuit loudness curve."}]},{"type":"paragraph","attrs":{"ref":"r64"},"content":[{"type":"text","text":"Loading, treble bleeds and wiring affect the control’s response too. Choose a taper for the useful adjustment range you need, then evaluate it in the intended circuit. A 500 kΩ audio pot and a 500 kΩ linear pot share a nominal end-to-end resistance but can feel very different when adjusted."}]}]},{"type":"container","attrs":{"ref":"r65"},"content":[{"type":"heading","attrs":{"ref":"r66","level":3},"content":[{"type":"text","text":"Choose electrically, then check physical fit"}]},{"type":"paragraph","attrs":{"ref":"r67"},"content":[{"type":"text","text":"Check shaft diameter, solid or split shaft, spline count, thread length, bushing diameter and the available cavity depth. A correct resistance is not enough if the knob or mounting hole is incompatible. Leave room for terminals, capacitor leads and any switch section. Avoid forcing a mismatched knob onto a shaft."}]},{"type":"paragraph","attrs":{"ref":"r68"},"content":[{"type":"text","text":"A practical specification includes resistance, measured value or tolerance, taper, mounting dimensions and mechanical construction. Smooth rotation, reliable contacts and consistent assembly matter. Brand and price alone do not establish an electrical improvement. If you are diagnosing crackle or intermittent output, inspect the connection and contact condition before deciding that a different nominal resistance is the solution."}]}]}]}}}}'::jsonb,'{"template_key":"pots","expected_intent":"pots","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"protected"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"protected"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"},"r25":{"kind":"node"},"r26":{"kind":"node"},"r27":{"kind":"node"},"r28":{"kind":"node"},"r29":{"kind":"node"},"r30":{"kind":"node"},"r31":{"kind":"node"},"r32":{"kind":"node"},"r33":{"kind":"node"},"r34":{"kind":"node"},"r35":{"kind":"protected"},"r36":{"kind":"node"},"r37":{"kind":"node"},"r38":{"kind":"node"},"r39":{"kind":"protected"},"r40":{"kind":"node"},"r41":{"kind":"node"},"r42":{"kind":"node"},"r43":{"kind":"node"},"r44":{"kind":"node"},"r45":{"kind":"node"},"r46":{"kind":"node"},"r47":{"kind":"node"},"r48":{"kind":"node"},"r49":{"kind":"node"},"r50":{"kind":"node"},"r51":{"kind":"protected"},"r52":{"kind":"node"},"r53":{"kind":"node"},"r54":{"kind":"node"},"r55":{"kind":"node"},"r56":{"kind":"protected"},"r57":{"kind":"node"},"r58":{"kind":"node"},"r59":{"kind":"node"},"r60":{"kind":"node"},"r61":{"kind":"node"},"r62":{"kind":"node"},"r63":{"kind":"node"},"r64":{"kind":"node"},"r65":{"kind":"node"},"r66":{"kind":"node"},"r67":{"kind":"node"},"r68":{"kind":"node"}},"slots":["main","further"]}'::jsonb),
('73a9f903-99ad-585b-a74d-b2d668dd1867','values','{"version":1,"title":"250K vs 500K Pots","slug":"250k-vs-500k-pots","category":"potentiometers","intro":"Compare pickup loading rather than treating familiar pot values as fixed rules for single coils and humbuckers.","seo_title":"250K vs 500K Pots","meta_description":"Compare pickup loading rather than treating familiar pot values as fixed rules for single coils and humbuckers.","indexable":true,"primary_intent":"values","related":["pots","taper","tone","lugs"],"tools":["signal"],"components":["potentiometers"],"published_at":"2026-10-04","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"The difference is the load"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"250 kΩ and 500 kΩ describe nominal end-to-end track resistance. In a conventional passive volume circuit, that track connects the signal-input node to ground. At full volume the wiper is close to the input end, but the track still presents a load. A 250 kΩ track draws more current for the same voltage than a 500 kΩ track, so the two values interact differently with the pickup."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"The pickup has impedance that changes with frequency. Together with cable capacitance and the connected controls, it forms a resonant electrical network. Lower resistive loading commonly reduces the prominence of that resonance. Increasing the pot value commonly allows a less damped response. Descriptions such as brighter or darker can be useful shorthand, but the measurable subject is voltage response, not an automatic judgement of tone quality."}]}]},{"type":"container","attrs":{"ref":"r5"},"content":[{"type":"heading","attrs":{"ref":"r6","level":2},"content":[{"type":"text","text":"Why the familiar conventions exist"}]},{"type":"paragraph","attrs":{"ref":"r7"},"content":[{"type":"text","text":"250 kΩ is a common starting point for many passive single-coil circuits; 500 kΩ is common for many passive humbucker circuits. Those choices have become conventions because they often make useful combinations with those pickup families. They are not consequences of the names alone. Pickups within each family vary in inductance, resistance and construction, and the external load is part of the result."}]},{"type":"container","attrs":{"ref":"r8"},"content":[{"type":"protected","attrs":{"ref":"r9"}}]},{"type":"paragraph","attrs":{"ref":"r10"},"content":[{"type":"text","text":"Do not apply passive-guitar conventions blindly to active electronics. A manufacturer may specify a much lower resistance for an active pickup or preamp. Changing that value can alter control behaviour without providing the expected passive-pickup effect."}]}]},{"type":"container","attrs":{"ref":"r11"},"content":[{"type":"heading","attrs":{"ref":"r12","level":2},"content":[{"type":"text","text":"The number on one pot is not the whole circuit"}]},{"type":"paragraph","attrs":{"ref":"r13"},"content":[{"type":"text","text":"Two 500 kΩ resistances connected directly in parallel have an equivalent resistance of 250 kΩ. That simple example explains why more than one connected control can matter. A tone branch includes capacitance, however, so its impedance is frequency-dependent and cannot always be replaced by a single resistance. Switch positions and multi-volume arrangements can also change which loads the pickup sees."}]},{"type":"paragraph","attrs":{"ref":"r14"},"content":[{"type":"text","text":"Cable capacitance is another important variable. Keep the cable and amplifier input constant when comparing pots. Otherwise a new cable can change the response at the same time as the control replacement, making it hard to attribute the difference. Signal Forge exposes assumptions for a bounded electrical comparison; read its supported wiring and pickup-selection limits rather than interpreting it as a prediction of a complete amplified sound."}]}]},{"type":"container","attrs":{"ref":"r15"},"content":[{"type":"heading","attrs":{"ref":"r16","level":2},"content":[{"type":"text","text":"Nominal value, tolerance and measurement"}]},{"type":"paragraph","attrs":{"ref":"r17"},"content":[{"type":"text","text":"A label gives the design value, not an exact measurement of every manufactured part. Measure between the two track ends with the circuit isolated when you need the actual resistance. Other connected components may create parallel paths and make an in-circuit reading misleading. Turn the shaft while checking the wiper measurements to distinguish the full track from a partial track."}]},{"type":"paragraph","attrs":{"ref":"r18"},"content":[{"type":"text","text":"A measured 500 kΩ-class part and another part with the same label can differ. That is a reason to specify tolerance and measured values, not a reason to invent special tonal properties for a material or logo. Replacement decisions should also preserve the required taper and physical fit."}]}]},{"type":"container","attrs":{"ref":"r19"},"content":[{"type":"heading","attrs":{"ref":"r20","level":2},"content":[{"type":"text","text":"Make a controlled choice"}]},{"type":"paragraph","attrs":{"ref":"r21"},"content":[{"type":"text","text":"First identify the existing circuit, pickup and pot specification. Decide what you want to change: overall loading, the adjustment range or a mechanical fault. Compare loading with a consistent pickup, cable, amplifier input and control setting. Change one electrical variable at a time and record the result."}]},{"type":"container","attrs":{"ref":"r22"},"content":[{"type":"heading","attrs":{"ref":"r23","level":3},"content":[{"type":"text","text":"Resistance does not define taper"}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"A 250 kΩ audio pot and a 500 kΩ audio pot differ in nominal resistance; a 500 kΩ audio pot and a 500 kΩ linear pot differ in taper. Treat those as separate decisions."}]}]},{"type":"paragraph","attrs":{"ref":"r25"},"content":[{"type":"text","text":"If the present full-volume response suits the instrument but the adjustment feels abrupt, a taper change may address the problem more directly than changing resistance. If a quieter setting loses useful high-frequency content, consider the volume circuit and a treble bleed rather than assuming that a larger pot value is the universal fix."}]}]}]}}}}'::jsonb,'{"template_key":"values","expected_intent":"values","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"protected"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"},"r25":{"kind":"node"}},"slots":["main"]}'::jsonb),
('d6ffa902-929f-5339-aa52-49043cda7606','taper','{"version":1,"title":"Audio vs Linear Taper Pots","slug":"audio-vs-linear-taper-pots","category":"potentiometers","intro":"Separate the resistance curve from the control’s in-circuit response, and choose a useful sweep for volume or tone.","seo_title":"Audio vs Linear Taper Pots","meta_description":"Separate the resistance curve from the control’s in-circuit response, and choose a useful sweep for volume or tone.","indexable":true,"primary_intent":"taper","related":["pots","values","bleeds"],"tools":["signal","bleed"],"components":["potentiometers"],"published_at":"2026-10-04","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Resistance and taper answer different questions"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"A pot’s nominal resistance is measured between the ends of the complete track. Taper describes the proportion of that resistance between the wiper and each end as the shaft rotates. A 500 kΩ linear pot and a 500 kΩ audio pot can therefore measure similarly end to end while producing different wiper readings halfway through their travel."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"For an approximately linear track, halfway rotation gives approximately half the full resistance on each side of the wiper. An audio or logarithmic track deliberately uses a different curve. Real audio tapers can be segmented approximations and come in different proportions; the word audio does not specify one universal transfer curve. Read the manufacturer’s drawing or curve when the sweep matters."}]}]},{"type":"container","attrs":{"ref":"r5"},"content":[{"type":"heading","attrs":{"ref":"r6","level":2},"content":[{"type":"text","text":"Why audio taper is common for volume"}]},{"type":"paragraph","attrs":{"ref":"r7"},"content":[{"type":"text","text":"Perceived loudness does not follow voltage in a simple linear way. An audio taper is commonly chosen to make volume adjustment more useful across the rotation range. That is a design convention, not proof that the knob position is a calibrated loudness control. Pickup impedance, the load and any bypass network affect the electrical response, while amplification and listening conditions affect what a player hears."}]},{"type":"paragraph","attrs":{"ref":"r8"},"content":[{"type":"text","text":"A linear pot can still be useful for volume when its adjustment range suits the player and circuit. The question is where the useful changes occur. If most of the audible change seems crowded into a small part of the travel, compare the actual taper and connected network before blaming the resistance value. Do not expect a different printed taper label to remove every interaction."}]}]},{"type":"container","attrs":{"ref":"r9"},"content":[{"type":"heading","attrs":{"ref":"r10","level":2},"content":[{"type":"text","text":"Tone-control sweep is a circuit result"}]},{"type":"paragraph","attrs":{"ref":"r11"},"content":[{"type":"text","text":"A conventional tone control varies resistance in a capacitor loading branch. It does not use the pot as exactly the same voltage divider as the volume circuit. Its frequency-dependent behaviour means that the resistance-versus-rotation curve and the pickup/load response both determine how the control feels."}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"Audio and linear tapers are both used for tone controls. One may give a more useful range in a particular instrument, but there is no rule that the component marked audio must be used for volume and the component marked linear must be used for tone. Compare the intended tone network and the player’s useful settings, including the region near the fully rolled-down position."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"Measure the curve, not just the label"}]},{"type":"container","attrs":{"ref":"r15"},"content":[{"type":"protected","attrs":{"ref":"r16"}}]},{"type":"paragraph","attrs":{"ref":"r17"},"content":[{"type":"text","text":"The direction matters. Turning clockwise in the installed orientation should produce the intended change; swapping the end functions changes the direction of the resistance sweep. A reversed audio taper is not equivalent to an ordinary audio taper installed backwards if the useful curve needs to run in the other direction."}]},{"type":"container","attrs":{"ref":"r18"},"content":[{"type":"heading","attrs":{"ref":"r19","level":3},"content":[{"type":"text","text":"Letter codes vary"}]},{"type":"paragraph","attrs":{"ref":"r20"},"content":[{"type":"text","text":"Do not infer audio or linear solely from an A or B printed on a casing without checking that manufacturer’s coding convention. Use the datasheet and measurement."}]}]}]},{"type":"container","attrs":{"ref":"r21"},"content":[{"type":"heading","attrs":{"ref":"r22","level":2},"content":[{"type":"text","text":"Treble bleeds can change the sweep too"}]},{"type":"paragraph","attrs":{"ref":"r23"},"content":[{"type":"text","text":"A capacitor between volume input and wiper adds a frequency-dependent bypass path. A resistor associated with it also changes how the network behaves, so a treble bleed can alter the apparent volume progression as well as the high-frequency balance. The original pot taper remains a component property, but the complete control response has changed."}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"Compare at the same knob position and also at matched practical output levels. Those comparisons answer different questions. An electrical model can show the effect of stated assumptions; it does not model perceived loudness. Use the Treble Bleed Designer to explore the network without treating its curve as a guaranteed listening result."}]}]},{"type":"container","attrs":{"ref":"r25"},"content":[{"type":"heading","attrs":{"ref":"r26","level":2},"content":[{"type":"text","text":"A useful specification"}]},{"type":"paragraph","attrs":{"ref":"r27"},"content":[{"type":"text","text":"Record nominal resistance, actual tolerance, taper family or curve, rotation direction and mounting requirements. If you like the existing sweep, replace like for like rather than changing taper incidentally during a repair. If the sweep is the problem, keep resistance and the surrounding circuit consistent while trying a different curve."}]},{"type":"paragraph","attrs":{"ref":"r28"},"content":[{"type":"text","text":"Mechanical quality, contact reliability and fit remain important. A premium label does not replace a taper specification. The best choice for the job is a control whose usable range, electrical load and physical dimensions are appropriate for the instrument."}]}]}]}}}}'::jsonb,'{"template_key":"taper","expected_intent":"taper","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"protected"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"},"r25":{"kind":"node"},"r26":{"kind":"node"},"r27":{"kind":"node"},"r28":{"kind":"node"}},"slots":["main"]}'::jsonb),
('1ea0a550-0a32-524d-a69a-d8c1e4aadd0d','tone','{"version":1,"title":"How a Guitar Tone Control Works","slug":"how-a-guitar-tone-control-works","category":"tone-controls","intro":"Understand the capacitor and potentiometer as a frequency-dependent loading branch toward ground, not an inline filter in the main signal path.","seo_title":"How a Guitar Tone Control Works","meta_description":"Understand the capacitor and potentiometer as a frequency-dependent loading branch toward ground, not an inline filter in the main signal path.","indexable":true,"primary_intent":"tone","related":["capacitor-values","pots","bleeds","modern-50s"],"tools":["signal","wiring"],"components":["capacitors"],"published_at":"2026-10-04","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"protected","attrs":{"ref":"r1"}},{"type":"container","attrs":{"ref":"r2"},"content":[{"type":"heading","attrs":{"ref":"r3","level":2},"content":[{"type":"text","text":"Start with the branch"}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"In a conventional passive tone circuit, the capacitor and the tone pot provide a path from a signal node toward ground. The main signal route still runs from the selected pickup to the volume input, through the wiper and to the output jack TIP. The tone network loads that signal; it is not simply a capacitor placed inline between pickup and output."}]},{"type":"paragraph","attrs":{"ref":"r5"},"content":[{"type":"text","text":"For the simple Modern arrangement described here, the branch originates at the volume signal-input lug 3. Other supported wiring arrangements can move that connection and change interactions. Use the diagram for the actual configuration rather than transferring a generic picture to every guitar. Volume lug 1 is ground, not the signal-input attachment for this branch."}]}]},{"type":"container","attrs":{"ref":"r6"},"content":[{"type":"heading","attrs":{"ref":"r7","level":2},"content":[{"type":"text","text":"Why capacitance makes the loading frequency-dependent"}]},{"type":"paragraph","attrs":{"ref":"r8"},"content":[{"type":"text","text":"A capacitor’s impedance changes with frequency. For an ideal capacitor, the magnitude of capacitive reactance is |Xc| = 1 / (2πfC). At a higher frequency, the same capacitor presents less reactance; at a higher capacitance, it presents less reactance at the same frequency. That is why this branch affects the electrical response differently across the spectrum."}]},{"type":"paragraph","attrs":{"ref":"r9"},"content":[{"type":"text","text":"The equation describes the capacitor, not the whole guitar. The pickup’s impedance, tone resistance, volume control and external load also contribute. A passive pickup has inductance, so this is not accurately reduced to an isolated single-pole RC filter with a universal cut-off frequency. A resonance and its damping can change as the controls move."}]}]},{"type":"container","attrs":{"ref":"r10"},"content":[{"type":"heading","attrs":{"ref":"r11","level":2},"content":[{"type":"text","text":"What the tone pot changes"}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"The tone pot changes the resistance associated with the capacitor’s path to ground. At the setting commonly called tone up, a large resistance limits the branch’s loading, but an ordinary pot still leaves a finite network connected. At tone down, the resistance is reduced and the capacitor has a stronger effect on the response. The physical direction depends on how the terminals are connected."}]},{"type":"paragraph","attrs":{"ref":"r13"},"content":[{"type":"text","text":"This is why the useful knob range depends on taper as well as the capacitor. A no-load tone control, where specified, disconnects at a particular end setting and should not be assumed equivalent to an ordinary pot. Check the actual part and circuit if you are comparing the fully open position."}]}]},{"type":"container","attrs":{"ref":"r14"},"content":[{"type":"heading","attrs":{"ref":"r15","level":2},"content":[{"type":"text","text":"Choose values as a network"}]},{"type":"container","attrs":{"ref":"r16"},"content":[{"type":"protected","attrs":{"ref":"r17"}}]},{"type":"paragraph","attrs":{"ref":"r18"},"content":[{"type":"text","text":"Common 0.022 µF and 0.047 µF choices are useful starting points, not single-coil or humbucker laws. At the same low tone resistance, the larger capacitor generally shifts the heavily affected region toward lower frequencies. At a more resistive tone setting, differences can be smaller and remain dependent on the rest of the circuit."}]}]},{"type":"container","attrs":{"ref":"r19"},"content":[{"type":"heading","attrs":{"ref":"r20","level":2},"content":[{"type":"text","text":"Separate specification from mythology"}]},{"type":"paragraph","attrs":{"ref":"r21"},"content":[{"type":"text","text":"Measured capacitance, tolerance, leakage where relevant, physical dimensions and reliable construction are useful specifications. The material name by itself does not establish an audible advantage. Two equivalent components used within their ratings obey the same circuit relationships; any claimed difference needs a controlled comparison and an identified electrical cause."}]},{"type":"paragraph","attrs":{"ref":"r22"},"content":[{"type":"text","text":"A capacitor voltage rating is a permitted operating limit, not a tone-intensity setting. A passive guitar normally produces small signals, but the replacement still needs a suitable rating and sound insulation. Avoid exposed leads that can contact grounded metal or a neighbouring terminal."}]}]},{"type":"container","attrs":{"ref":"r23"},"content":[{"type":"heading","attrs":{"ref":"r24","level":2},"content":[{"type":"text","text":"Understand, compare, then wire"}]},{"type":"paragraph","attrs":{"ref":"r25"},"content":[{"type":"text","text":"Identify the signal node and ground return in the wiring reference before soldering. Keep the jack TIP and sleeve identities distinct. Inspect for solder bridges and unintended shorts after assembly. A tone control that mutes the entire guitar may have a wiring fault; do not assume that the capacitor value alone explains a total loss of output."}]},{"type":"container","attrs":{"ref":"r26"},"content":[{"type":"heading","attrs":{"ref":"r27","level":3},"content":[{"type":"text","text":"A model has boundaries"}]},{"type":"paragraph","attrs":{"ref":"r28"},"content":[{"type":"text","text":"Signal Forge provides an electrical comparison for supported assumptions and configurations. Read those limits. It does not predict the amplifier, speaker, acoustic level or a player’s preference."}]}]},{"type":"paragraph","attrs":{"ref":"r29"},"content":[{"type":"text","text":"For a useful experiment, hold the pickup, cable and volume constant, then compare capacitance and tone positions. Document the settings so the comparison is repeatable. The aim is to understand an adjustment, not to find a universally correct capacitor."}]}]}]}}}}'::jsonb,'{"template_key":"tone","expected_intent":"tone","refs":{"r1":{"kind":"protected"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"protected"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"},"r25":{"kind":"node"},"r26":{"kind":"node"},"r27":{"kind":"node"},"r28":{"kind":"node"},"r29":{"kind":"node"}},"slots":["main"]}'::jsonb),
('f5720f9c-8445-5e3b-ada8-6ab1791dd946','capacitor-values','{"version":1,"title":"0.022µF vs 0.047µF Guitar Tone Capacitors","slug":"022-vs-047-tone-capacitors","category":"tone-controls","intro":"Compare capacitance in the tone branch, with the source impedance and control settings that make the comparison meaningful.","seo_title":"0.022µF vs 0.047µF Guitar Tone Capacitors","meta_description":"Compare capacitance in the tone branch, with the source impedance and control settings that make the comparison meaningful.","indexable":true,"primary_intent":"capacitor-values","related":["tone","pots","caps"],"tools":["signal"],"components":["capacitors"],"published_at":"2026-10-04","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Read the value correctly"}]},{"type":"container","attrs":{"ref":"r3"},"content":[{"type":"protected","attrs":{"ref":"r4"}}]},{"type":"paragraph","attrs":{"ref":"r5"},"content":[{"type":"text","text":"The 0.047 µF value is a little more than twice 0.022 µF. It is not a resistance and it does not state a capacitor’s physical size or construction. Unit errors are easy when reading tiny markings, so confirm the part’s code against its documentation or a suitable capacitance measurement before installation."}]},{"type":"paragraph","attrs":{"ref":"r6"},"content":[{"type":"text","text":"A nominal value is a target. Tolerance describes the allowed deviation, and an actual measurement helps make comparisons repeatable. If a circuit’s attached components interfere with measurement, isolate the capacitor rather than interpreting the reading as a definite component value."}]}]},{"type":"container","attrs":{"ref":"r7"},"content":[{"type":"heading","attrs":{"ref":"r8","level":2},"content":[{"type":"text","text":"What increasing capacitance changes"}]},{"type":"paragraph","attrs":{"ref":"r9"},"content":[{"type":"text","text":"For an ideal capacitor, |Xc| = 1 / (2πfC). At the same frequency, 0.047 µF therefore has lower capacitive reactance than 0.022 µF. In the conventional tone-loading branch, that changes the impedance presented toward ground. The result depends on the tone resistance, pickup impedance and the other connected loads."}]},{"type":"paragraph","attrs":{"ref":"r10"},"content":[{"type":"text","text":"At a low tone-resistance setting, the larger value generally affects a lower part of the frequency range and can give a different rolled-down response. That is more precise than saying that one value simply removes twice as much treble. The full pickup network can have resonant behaviour; the effect is not a universal cut-off determined by the capacitor alone."}]}]},{"type":"container","attrs":{"ref":"r11"},"content":[{"type":"heading","attrs":{"ref":"r12","level":2},"content":[{"type":"text","text":"Compare at more than one tone position"}]},{"type":"paragraph","attrs":{"ref":"r13"},"content":[{"type":"text","text":"At tone up, the tone resistance limits the branch’s loading, so a capacitance difference may be less prominent than at tone down. At intermediate positions, taper controls which resistance is being used. Knob markings do not guarantee the same electrical resistance across two different pots."}]},{"type":"paragraph","attrs":{"ref":"r14"},"content":[{"type":"text","text":"For a meaningful experiment, keep the same pot, pickup, volume position, cable and amplifier input. Compare the capacitors at fixed settings, including the setting you actually use. If the pot or cable is changed at the same time, you have changed more than one variable and cannot confidently assign the result to capacitance."}]}]},{"type":"container","attrs":{"ref":"r15"},"content":[{"type":"heading","attrs":{"ref":"r16","level":2},"content":[{"type":"text","text":"Conventions are useful, not compulsory"}]},{"type":"paragraph","attrs":{"ref":"r17"},"content":[{"type":"text","text":"0.022 µF is often associated with humbucker circuits and 0.047 µF with single-coil circuits. Both values also appear outside those conventions. Pickup inductance, desired adjustment range and the original circuit design are better reasons for a choice than the pickup family name on its own."}]},{"type":"paragraph","attrs":{"ref":"r18"},"content":[{"type":"text","text":"A player who rarely rolls tone down may care more about the available intermediate range. Another player may want a particular fully rolled-down response. Neither preference makes one capacitor universally correct. Begin with the existing specification if repairing a working instrument, and change deliberately if experimenting."}]}]},{"type":"container","attrs":{"ref":"r19"},"content":[{"type":"heading","attrs":{"ref":"r20","level":2},"content":[{"type":"text","text":"What to specify when buying a part"}]},{"type":"paragraph","attrs":{"ref":"r21"},"content":[{"type":"text","text":"Choose the required capacitance, an appropriate tolerance and voltage rating, sensible lead spacing and dimensions that fit the cavity. Reliability, insulation and repeatable assembly are practical benefits. They do not require a claim that a particular dielectric or historic casing adds an otherwise unexplained sound."}]},{"type":"container","attrs":{"ref":"r22"},"content":[{"type":"heading","attrs":{"ref":"r23","level":3},"content":[{"type":"text","text":"Equivalent values need evidence for unequal claims"}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"A premium component can offer useful construction or QC. Do not infer audible superiority from its material name, colour or price alone. Identify a measurable difference before assigning it an electrical explanation."}]}]},{"type":"paragraph","attrs":{"ref":"r25"},"content":[{"type":"text","text":"Make sure capacitor leads cannot short to the casing or neighbouring terminals. A good component with poor installation can produce a fault that overwhelms the subtle comparison you intended to make."}]}]},{"type":"container","attrs":{"ref":"r26"},"content":[{"type":"heading","attrs":{"ref":"r27","level":2},"content":[{"type":"text","text":"A repeatable selection process"}]},{"type":"paragraph","attrs":{"ref":"r28"},"content":[{"type":"text","text":"Write down the current component value and the symptom or change you want. Check that the tone branch is wired correctly first. Compare candidate values with the same assumptions in Signal Forge, then use the physical wiring reference to verify the connection. Respect the tool’s supported-model limits rather than treating a simulated curve as a complete listening test."}]},{"type":"paragraph","attrs":{"ref":"r29"},"content":[{"type":"text","text":"Keep a note of the measured capacitance and the settings used in the comparison. If neither value gives the useful control range you want, consider the tone taper and surrounding loading before accumulating more parts. This makes the choice a controlled circuit decision instead of a search for a mythical capacitor."}]}]}]}}}}'::jsonb,'{"template_key":"capacitor-values","expected_intent":"capacitor-values","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"protected"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"},"r25":{"kind":"node"},"r26":{"kind":"node"},"r27":{"kind":"node"},"r28":{"kind":"node"},"r29":{"kind":"node"}},"slots":["main"]}'::jsonb),
('e717f888-6184-577c-aeb6-126b63c48204','bleeds','{"version":1,"title":"Choosing a treble bleed in context","slug":"treble-bleeds","category":"treble-bleeds","intro":"A treble bleed changes a volume circuit. Its effect depends on the pickup, pots, controls and load.","seo_title":"Treble Bleeds Explained","meta_description":"Why volume changes can alter high-frequency response, what the bypass networks do and how to compare them without a universal recipe.","indexable":true,"primary_intent":"bleeds","related":["taper","pots","lugs","modern-50s"],"tools":["bleed","signal"],"components":["treble-bleeds"],"published_at":null,"content_updated_at":"2026-10-04","body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Why response changes with volume"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"A passive pickup, volume control and cable form an interacting impedance network. Moving the wiper changes the source impedance presented to the cable capacitance and input load. The result can change the high-frequency voltage response as well as the output level."}]}]},{"type":"container","attrs":{"ref":"r4"},"content":[{"type":"heading","attrs":{"ref":"r5","level":2},"content":[{"type":"text","text":"What the bypass does"}]},{"type":"paragraph","attrs":{"ref":"r6"},"content":[{"type":"text","text":"A treble bleed connects between volume input and wiper. A capacitor provides a frequency-dependent path around part of the volume resistance. A parallel resistor adds a resistive path and changes the effective volume-control behaviour. This is a circuit change, not a universal repair."}]}]},{"type":"container","attrs":{"ref":"r7"},"content":[{"type":"heading","attrs":{"ref":"r8","level":2},"content":[{"type":"text","text":"Capacitor-only and parallel RC"}]},{"type":"paragraph","attrs":{"ref":"r9"},"content":[{"type":"text","text":"The supported PRS-style example uses 180 pF. The capacitor-only example uses 1 nF. The Duncan-style example uses 1 nF and 150 kΩ in parallel. These are existing shared circuit choices; brand names describe the convention, not measured pickup data or a guarantee for every instrument."}]}]},{"type":"container","attrs":{"ref":"r10"},"content":[{"type":"heading","attrs":{"ref":"r11","level":2},"content":[{"type":"text","text":"Compare the surrounding circuit"}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"Pot resistance and taper, pickup electrical assumptions, cable capacitance, input resistance and control position all matter. There is no universally best network. Compare at the same volume with the same assumptions before choosing a preference."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"Understand the comparison"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"Signal Lab models electrical voltage transfer for Modern wiring with Neck or Bridge selected. Its same-volume A/B compares the circuit against no bleed. Designer uses a full-volume reference and supports deeper network exploration. Neither models acoustic SPL, amplifier or speaker response, hearing, or perceived loudness."}]}]},{"type":"container","attrs":{"ref":"r16"},"content":[{"type":"heading","attrs":{"ref":"r17","level":2},"content":[{"type":"text","text":"Choose and check"}]},{"type":"paragraph","attrs":{"ref":"r18"},"content":[{"type":"text","text":"Start with the smallest change that answers your need. Verify the input and wiper terminals, leave the casing ground separate, and compare the wiring diagram before soldering. A correct equivalent network follows the same electrical laws regardless of branding."}]}]},{"type":"container","attrs":{"ref":"r19"},"content":[{"type":"protected","attrs":{"ref":"r20"}}]}]},"further":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r21"},"content":[{"type":"heading","attrs":{"ref":"r22","level":3},"content":[{"type":"text","text":"Volume changes more than the level"}]},{"type":"paragraph","attrs":{"ref":"r23"},"content":[{"type":"text","text":"A passive pickup, volume pot, cable capacitance and amplifier input form an interacting impedance network. Moving the wiper changes attenuation and the impedance driving the load. As a result, rolling down can change high-frequency voltage response as well as overall output. How noticeable that is depends on the circuit and listening conditions."}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"A treble bleed supplies an additional path between volume signal input and wiper. In Apparition’s convention those are lug 3 and lug 2. It is not a tone capacitor wired to ground, and it does not remove the need for the pot’s normal ground connection. The same capacitor type can do a different job when connected to different nodes."}]}]},{"type":"container","attrs":{"ref":"r25"},"content":[{"type":"heading","attrs":{"ref":"r26","level":3},"content":[{"type":"text","text":"Capacitor-only: a frequency-dependent bypass"}]},{"type":"paragraph","attrs":{"ref":"r27"},"content":[{"type":"text","text":"A capacitor between input and wiper provides a bypass whose impedance falls with increasing frequency. It allows more of the higher-frequency signal around part of the volume resistance. The capacitance controls how that bypass interacts with the pot and load; it does not correspond to a universal amount of preserved treble."}]},{"type":"paragraph","attrs":{"ref":"r28"},"content":[{"type":"text","text":"A network that helps at one volume setting can give an overly prominent high-frequency balance at another. Larger capacitance also extends the bypass effect further down in frequency. Evaluate several useful positions rather than accepting a pleasing full-volume comparison as evidence: at full volume there is little resistance between input and wiper for the bleed to bypass."}]}]},{"type":"container","attrs":{"ref":"r29"},"content":[{"type":"heading","attrs":{"ref":"r30","level":3},"content":[{"type":"text","text":"Adding a resistor changes the network"}]},{"type":"container","attrs":{"ref":"r31"},"content":[{"type":"protected","attrs":{"ref":"r32"}}]},{"type":"paragraph","attrs":{"ref":"r33"},"content":[{"type":"text","text":"A parallel resistor is connected across the same input and wiper nodes as the capacitor. It can alter volume-control progression as well as response. A series resistor belongs in the capacitor branch and produces a different network; the two arrangements are not interchangeable just because the component values match."}]},{"type":"paragraph","attrs":{"ref":"r34"},"content":[{"type":"text","text":"The existing supported examples include 180 pF capacitor-only, 1 nF capacitor-only and 1 nF with 150 kΩ in parallel. These are comparison starting points from the existing tools, not newly invented universal recommendations. The Treble Bleed Designer provides more detailed exploration; inspect its declared topology and assumptions."}]}]},{"type":"container","attrs":{"ref":"r35"},"content":[{"type":"heading","attrs":{"ref":"r36","level":3},"content":[{"type":"text","text":"Pot taper, pickup and load still matter"}]},{"type":"paragraph","attrs":{"ref":"r37"},"content":[{"type":"text","text":"A bleed network changes the effective circuit around the moving wiper, so the same components can behave differently with a different pot resistance or taper. Pickup inductance and resistance, cable capacitance and input resistance also affect the result. A recipe that works in one guitar is not evidence that it is optimal in every other guitar."}]},{"type":"paragraph","attrs":{"ref":"r38"},"content":[{"type":"text","text":"Compare like with like. Hold pickup selection, cable, input and control position constant for a circuit A/B. A matched-output listening comparison is useful too, but it answers a different question from a same-knob-position comparison. Do not confuse modelled voltage transfer with perceived loudness or the response of the complete amplifier and speaker."}]}]},{"type":"container","attrs":{"ref":"r39"},"content":[{"type":"heading","attrs":{"ref":"r40","level":3},"content":[{"type":"text","text":"Choose the smallest useful change"}]},{"type":"paragraph","attrs":{"ref":"r41"},"content":[{"type":"text","text":"First decide whether you need the quieter setting to retain more high-frequency content, a different volume sweep or both. Compare no bleed with capacitor-only and RC options. Include low, middle and high volume settings and listen for an adjustment range that remains useful. There is no requirement to install a bleed in a circuit that already behaves as you want."}]},{"type":"container","attrs":{"ref":"r42"},"content":[{"type":"heading","attrs":{"ref":"r43","level":3},"content":[{"type":"text","text":"Network names are not pickup data"}]},{"type":"paragraph","attrs":{"ref":"r44"},"content":[{"type":"text","text":"Names such as PRS-style or Duncan-style identify a familiar convention. They do not supply measured pickup parameters and do not guarantee the same result across instruments."}]}]},{"type":"paragraph","attrs":{"ref":"r45"},"content":[{"type":"text","text":"If the volume sweep is already the problem, changing the network can complicate diagnosis. Record the pot’s resistance and taper, establish a baseline without the bleed, then compare one network at a time."}]}]},{"type":"container","attrs":{"ref":"r46"},"content":[{"type":"heading","attrs":{"ref":"r47","level":3},"content":[{"type":"text","text":"Wire input to wiper, then inspect"}]},{"type":"paragraph","attrs":{"ref":"r48"},"content":[{"type":"text","text":"Verify lug 3 as signal input and lug 2 as the wiper/output before adding the network. Physical left and right reverse with viewing orientation. Insulate exposed leads as needed and leave clearance around grounded casings and adjacent terminals. The normal output remains wiper/lug 2 → jack TIP; sleeve is the return connection."}]},{"type":"paragraph","attrs":{"ref":"r49"},"content":[{"type":"text","text":"Use the Designer to experiment, then the wiring reference for the actual supported layout. Component shopping comes after that decision: capacitance, resistance, tolerance, dimensions and assembly quality are the useful specifications. Avoid buying a network solely because a branded recipe promises to preserve an undefined perfect tone."}]}]}]}}}}'::jsonb,'{"template_key":"bleeds","expected_intent":"bleeds","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"protected"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"},"r25":{"kind":"node"},"r26":{"kind":"node"},"r27":{"kind":"node"},"r28":{"kind":"node"},"r29":{"kind":"node"},"r30":{"kind":"node"},"r31":{"kind":"node"},"r32":{"kind":"protected"},"r33":{"kind":"node"},"r34":{"kind":"node"},"r35":{"kind":"node"},"r36":{"kind":"node"},"r37":{"kind":"node"},"r38":{"kind":"node"},"r39":{"kind":"node"},"r40":{"kind":"node"},"r41":{"kind":"node"},"r42":{"kind":"node"},"r43":{"kind":"node"},"r44":{"kind":"node"},"r45":{"kind":"node"},"r46":{"kind":"node"},"r47":{"kind":"node"},"r48":{"kind":"node"},"r49":{"kind":"node"}},"slots":["main","further"]}'::jsonb),
('d5b80fb3-5f15-56b0-ae9b-bf0f0ce5ca03','lugs','{"version":1,"title":"Guitar Pot Lug Numbering & Wiring","slug":"guitar-pot-lug-numbering-wiring","category":"wiring","intro":"Identify the wiper and track ends, apply Apparition’s terminal convention and avoid mirrored-view wiring mistakes.","seo_title":"Guitar Pot Lug Numbering & Wiring","meta_description":"Identify the wiper and track ends, apply Apparition’s terminal convention and avoid mirrored-view wiring mistakes.","indexable":true,"primary_intent":"lugs","related":["pots","tone","ground","toggle-guide","grounding-guide"],"tools":["wiring","signal"],"components":["potentiometers"],"published_at":"2026-10-04","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"protected","attrs":{"ref":"r1"}},{"type":"container","attrs":{"ref":"r2"},"content":[{"type":"heading","attrs":{"ref":"r3","level":2},"content":[{"type":"text","text":"Terminal identity comes before left and right"}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"A conventional three-terminal pot has two track-end terminals and a wiper terminal. The wiper is commonly the middle terminal on familiar guitar pots, but the part drawing is the authority for the component you are holding. Push-pull switches, stacked controls and unusual footprints may add terminals that belong to another function."}]},{"type":"paragraph","attrs":{"ref":"r5"},"content":[{"type":"text","text":"A diagram viewed from the rear is mirrored relative to a front view. A photograph without a stated viewpoint is therefore a poor basis for assigning functions by left and right. Identify the shaft, body and viewing orientation, then verify the terminal functions before using a numbered circuit reference."}]}]},{"type":"container","attrs":{"ref":"r6"},"content":[{"type":"heading","attrs":{"ref":"r7","level":2},"content":[{"type":"text","text":"Apparition’s volume convention"}]},{"type":"container","attrs":{"ref":"r8"},"content":[{"type":"protected","attrs":{"ref":"r9"}}]},{"type":"paragraph","attrs":{"ref":"r10"},"content":[{"type":"text","text":"The simple main path is pickup/selector → volume lug 3 → wiper/lug 2 → output jack TIP. The end-to-end track between lugs 3 and 1 loads the signal, while the wiper divides the voltage along it. This reference describes functions, not a universal left-to-right view of every manufactured pot."}]},{"type":"paragraph","attrs":{"ref":"r11"},"content":[{"type":"text","text":"For the Modern tone-loading branch described in these guides, the signal node at volume lug 3 feeds the tone network toward ground. Do not move that signal attachment to grounded volume lug 1. A treble bleed, by contrast, connects between signal input lug 3 and wiper lug 2. Those are different networks with different jobs."}]}]},{"type":"container","attrs":{"ref":"r12"},"content":[{"type":"heading","attrs":{"ref":"r13","level":2},"content":[{"type":"text","text":"Check with a meter before soldering"}]},{"type":"paragraph","attrs":{"ref":"r14"},"content":[{"type":"text","text":"With the pot electrically isolated, measure between the track ends: the reading should remain approximately the full resistance as the shaft rotates. Measure between the wiper and one end: the reading should change through the travel. The reading from the wiper to the other end changes in the opposite direction."}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"These checks establish the moving contact and direction of the sweep. They do not tell you that an in-circuit measurement equals the printed value when other resistances are connected in parallel. If readings do not make sense, disconnect the relevant path or consult the part documentation rather than renumbering a diagram to fit a guess."}]},{"type":"container","attrs":{"ref":"r16"},"content":[{"type":"heading","attrs":{"ref":"r17","level":3},"content":[{"type":"text","text":"Separate a switch from the pot"}]},{"type":"paragraph","attrs":{"ref":"r18"},"content":[{"type":"text","text":"A push-pull control includes a switch contact set as well as potentiometer terminals. Identify both from the manufacturer’s drawing; a switch common is not the volume wiper."}]}]}]},{"type":"container","attrs":{"ref":"r19"},"content":[{"type":"heading","attrs":{"ref":"r20","level":2},"content":[{"type":"text","text":"TIP is signal; sleeve is return"}]},{"type":"paragraph","attrs":{"ref":"r21"},"content":[{"type":"text","text":"A supported mono output jack has a TIP contact for signal and a sleeve contact for return. Identify the actual contact with the jack drawing and continuity checks; the solder-lug position is not a reliable substitute for contact identity. Inserting an unconnected plug can help establish which lug reaches the plug tip and which reaches the sleeve."}]},{"type":"paragraph","attrs":{"ref":"r22"},"content":[{"type":"text","text":"The pot casing can be used as part of the ground network when the intended wiring calls for it, but the casing is not the wiper. Avoid solder bridges from signal terminals to the casing. Ground and shielding have related but distinct roles, so follow the complete return and shield references rather than assuming every bare conductor is interchangeable."}]}]},{"type":"container","attrs":{"ref":"r23"},"content":[{"type":"heading","attrs":{"ref":"r24","level":2},"content":[{"type":"text","text":"Translate the circuit into physical connections"}]},{"type":"paragraph","attrs":{"ref":"r25"},"content":[{"type":"text","text":"Choose the supported configuration in the Wiring Diagram Generator and inspect its connection list before soldering. Confirm part orientation, terminal identity and clearance in the instrument. Route wires so movement of the controls or closing the cavity cannot press exposed conductors together."}]},{"type":"paragraph","attrs":{"ref":"r26"},"content":[{"type":"text","text":"After assembly, inspect each joint and check intended continuity with the instrument disconnected from equipment. A visual similarity to a diagram is not evidence of an electrical connection. Conversely, a connection can be electrically equivalent even when the physical wire route looks different; terminal identity is what matters."}]}]},{"type":"container","attrs":{"ref":"r27"},"content":[{"type":"heading","attrs":{"ref":"r28","level":2},"content":[{"type":"text","text":"Keep the reference specific"}]},{"type":"paragraph","attrs":{"ref":"r29"},"content":[{"type":"text","text":"Multi-volume instruments, special switching and alternative tone connections can introduce additional interactions. The simple path above is the starting convention, not permission to replace a configuration-specific diagram. Read the guide for the intended circuit and use the tool within its supported capabilities."}]},{"type":"paragraph","attrs":{"ref":"r30"},"content":[{"type":"text","text":"If output disappears, isolate the cable and jack before assuming a bad pot. Check for signal-to-ground shorts, a missing wiper connection and mistaken selector contacts. Correct identification and measurement usually provide more useful evidence than replacing components at random."}]}]}]}}}}'::jsonb,'{"template_key":"lugs","expected_intent":"lugs","refs":{"r1":{"kind":"protected"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"protected"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"},"r25":{"kind":"node"},"r26":{"kind":"node"},"r27":{"kind":"node"},"r28":{"kind":"node"},"r29":{"kind":"node"},"r30":{"kind":"node"}},"slots":["main"]}'::jsonb),
('7c42c51b-f554-5dcd-a790-c0c3bcf3c418','modern-50s','{"version":1,"title":"Modern vs 50s Les Paul Wiring","slug":"modern-vs-50s-les-paul-wiring","category":"wiring","intro":"Compare the tone-branch connection and the resulting control interactions, without treating either arrangement as a universal upgrade.","seo_title":"Modern vs 50s Les Paul Wiring","meta_description":"Compare the tone-branch connection and the resulting control interactions, without treating either arrangement as a universal upgrade.","indexable":true,"primary_intent":"modern-50s","related":["tone","lp-controls","bleeds","lugs","caps"],"tools":["signal","wiring"],"components":["potentiometers"],"published_at":"2026-10-05","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"The connection that changes"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"In the supported Les Paul circuit, the selected pickup feeds its volume signal-input lug 3, the wiper/lug 2 feeds the selector and the selector output reaches jack TIP. Lug 1 belongs to ground. Modern versus 50s wiring changes where the tone-loading branch attaches; it does not turn the tone capacitor into an inline component in that main path."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"Modern connects the branch to volume signal-input lug 3. The supported 50s arrangement takes its tone feed from wiper/lug 2 instead. The Generator also represents the corresponding tone-pot terminal arrangement for that configuration. Use its complete diagram rather than moving one wire on the basis of an unlabelled photograph."}]}]},{"type":"container","attrs":{"ref":"r5"},"content":[{"type":"heading","attrs":{"ref":"r6","level":2},"content":[{"type":"text","text":"The tone branch sees a different node"}]},{"type":"paragraph","attrs":{"ref":"r7"},"content":[{"type":"text","text":"At full volume the wiper is near the input end of the track, so the two attachment nodes can be close electrically. As the volume changes, resistance separates them. Moving the tone branch from input to output therefore changes how tone resistance and capacitance interact with the volume divider and external load."}]},{"type":"paragraph","attrs":{"ref":"r8"},"content":[{"type":"text","text":"Players often describe 50s wiring as retaining more clarity during volume reduction. The useful electrical explanation is the changed loading and control interaction, not a claim that old wiring creates extra high frequencies. Pickup impedance, cable capacitance, control settings and the amplifier input all matter. A familiar name does not define a guaranteed audible outcome."}]}]},{"type":"container","attrs":{"ref":"r9"},"content":[{"type":"heading","attrs":{"ref":"r10","level":2},"content":[{"type":"text","text":"Volume and tone are not independent adjustments"}]},{"type":"paragraph","attrs":{"ref":"r11"},"content":[{"type":"text","text":"Turning tone changes a frequency-dependent load. In the 50s arrangement that load acts on the volume-output node, so the perceived volume progression and tonal adjustment can interact differently from Modern. It is normal for a useful setting on one arrangement not to correspond to the same knob number on the other."}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"This is separate from independent versus dependent two-volume wiring. Moving a tone feed does not by itself change the supported volume input/wiper assignments. In the conventional combined-pickup circuit, turning one volume completely down can still ground the common selector output and mute both pickups."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"Consider a treble bleed separately"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"A treble bleed bypass connects volume input lug 3 to wiper lug 2. It is a different network from the tone branch. Combining it with a different tone-feed position changes the complete circuit again; do not assume that two changes which each seem useful will automatically combine into a better result."}]},{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"The existing Kit Builder does not offer a bleed with its 50s wiring configuration. Respect that boundary instead of treating an explanatory guide as an unsupported purchasing option. When comparing Modern and a bleed, hold pickup, cable, load and useful volume positions constant."}]}]},{"type":"container","attrs":{"ref":"r17"},"content":[{"type":"heading","attrs":{"ref":"r18","level":2},"content":[{"type":"text","text":"Compare the wiring, then prepare the bench"}]},{"type":"paragraph","attrs":{"ref":"r19"},"content":[{"type":"text","text":"Record the existing connections and verify the actual pot and jack terminal identities. Front and rear views can reverse apparent left and right. Select the supported Les Paul wiring in the Generator and follow the complete connection list, including the ground return and the tone terminals."}]},{"type":"paragraph","attrs":{"ref":"r20"},"content":[{"type":"text","text":"Check insulation, cavity clearance and continuity with the instrument disconnected before testing it through equipment. Keep the original component values constant for a meaningful wiring comparison. Changing taper, capacitance and wiring simultaneously makes the result difficult to attribute."}]}]},{"type":"container","attrs":{"ref":"r21"},"content":[{"type":"heading","attrs":{"ref":"r22","level":2},"content":[{"type":"text","text":"Know which tool answers which question"}]},{"type":"paragraph","attrs":{"ref":"r23"},"content":[{"type":"text","text":"Signal Forge can inspect the supported circuit topology, while the Wiring Diagram Generator supplies a physical connection reference. The current electrical-response model is bounded to supported Modern single-pickup arrangements; this article does not extend it to 50s or combined-pickup response."}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"Use the available graph to understand connections, and a controlled practical comparison to decide which adjustment range suits the instrument. Neither arrangement is universally correct. A repair should first restore intended connections; an experiment should change one defined variable at a time."}]}]}]}}}}'::jsonb,'{"template_key":"modern-50s","expected_intent":"modern-50s","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"}},"slots":["main"]}'::jsonb),
('5f22ef7c-0efb-5fb0-adea-6eebcc55c06e','lp-controls','{"version":1,"title":"How Les Paul Controls Work","slug":"how-les-paul-controls-work","category":"wiring","intro":"Follow two pickup channels through their volume and tone controls, the selector and a shared output.","seo_title":"How Les Paul Controls Work","meta_description":"Follow two pickup channels through their volume and tone controls, the selector and a shared output.","indexable":true,"primary_intent":"lp-controls","related":["pots","modern-50s","toggle-guide","tone"],"tools":["signal","wiring"],"components":["potentiometers"],"published_at":"2026-10-05","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Two channels meet at the selector"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"The supported passive Les Paul-style circuit has a volume and a tone control for each pickup. Each pickup signal feeds the corresponding volume input; each volume wiper supplies one selector input. The selector chooses neck, bridge or both and sends the resulting connection to the output jack TIP."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"Four knobs do not mean four isolated signal sources. The pickup channels share the output path and ground network. In the combined position they can load one another through that connection, so a control can influence the result differently than it does with only one pickup selected."}]}]},{"type":"container","attrs":{"ref":"r5"},"content":[{"type":"heading","attrs":{"ref":"r6","level":2},"content":[{"type":"text","text":"A volume pot is a divider and a load"}]},{"type":"paragraph","attrs":{"ref":"r7"},"content":[{"type":"text","text":"Apparition identifies volume lug 3 as signal input, lug 2 as wiper/output and lug 1 as ground. The full track loads the pickup while the wiper selects an output point along it. Turning the knob changes attenuation and the impedance presented to the cable and amplifier input."}]},{"type":"paragraph","attrs":{"ref":"r8"},"content":[{"type":"text","text":"The nominal resistance and taper are different specifications. Resistance contributes to loading; taper changes resistance progression with rotation. A knob set to five is not a calibrated promise of half loudness, and replacing a control with a different taper can alter the useful sweep even when its nominal resistance stays the same."}]}]},{"type":"container","attrs":{"ref":"r9"},"content":[{"type":"heading","attrs":{"ref":"r10","level":2},"content":[{"type":"text","text":"Why one volume can affect both pickups"}]},{"type":"paragraph","attrs":{"ref":"r11"},"content":[{"type":"text","text":"In the conventional supported wiring, the both position connects the two wiper outputs to a common output. With a volume fully down, its wiper approaches the grounded end of the track. That can pull the shared output toward ground and mute the combined signal. This behaviour does not by itself identify a faulty selector."}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"At intermediate positions the interaction is more nuanced than adding two independently fixed levels. Pickup impedances, control resistance and the connected loads matter. The current response tool does not validate the combined-pickup response, so its single-pickup curve should not be presented as a simulation of this blend."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"Each tone control loads a signal node"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"A tone pot and capacitor form a frequency-dependent loading branch toward ground. In Modern wiring that branch originates at volume input lug 3; in the supported 50s configuration its feed comes from the volume wiper lug 2. The main path still reaches the jack without an inline tone capacitor."}]},{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"The tone setting, capacitance and pickup impedance together influence the response. A larger capacitance does not establish a universally better sound, and a capacitor material name does not supply an electrical explanation. Choose values deliberately and inspect the specific wiring before attributing a change to a component."}]}]},{"type":"container","attrs":{"ref":"r17"},"content":[{"type":"heading","attrs":{"ref":"r18","level":2},"content":[{"type":"text","text":"Selected does not mean every other node disappears"}]},{"type":"paragraph","attrs":{"ref":"r19"},"content":[{"type":"text","text":"A selector opens and closes contacts; it does not rewrite the whole harness. The disconnected channel still has its own controls and ground connections, while the selected contacts establish which output paths are joined. A switch label must be checked against the actual contact arrangement."}]},{"type":"paragraph","attrs":{"ref":"r20"},"content":[{"type":"text","text":"Do not assign contact functions by the direction of a photograph alone. The correct common, pickup inputs and ground/shield point depend on the part. Use the part documentation and continuity checks alongside the Generator’s supported reference."}]}]},{"type":"container","attrs":{"ref":"r21"},"content":[{"type":"heading","attrs":{"ref":"r22","level":2},"content":[{"type":"text","text":"A useful test sequence"}]},{"type":"paragraph","attrs":{"ref":"r23"},"content":[{"type":"text","text":"Begin with a known-good cable and an identified jack TIP/sleeve pair. Select one pickup, check its volume through the travel and then its tone adjustment. Repeat for the other pickup before checking the combined position. This isolates a channel problem from a shared output fault."}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"If there is no output in every position, inspect the shared selector output and jack before replacing four controls. If only one pickup fails, follow that channel from pickup hot to volume input and wiper. Keep a note of the configuration and use continuity evidence rather than the visual neatness of a joint."}]}]}]}}}}'::jsonb,'{"template_key":"lp-controls","expected_intent":"lp-controls","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"}},"slots":["main"]}'::jsonb),
('e5b5beaa-39f1-58d9-a2cf-4a4645a5a7e0','toggle-guide','{"version":1,"title":"Guitar Three-Way Toggle Switch Wiring Explained","slug":"guitar-three-way-toggle-switch-wiring","category":"pickups","intro":"Identify pickup inputs, switched output and ground by contact function, not by a generic photograph.","seo_title":"Guitar Three-Way Toggle Switch Wiring Explained","meta_description":"Identify pickup inputs, switched output and ground by contact function, not by a generic photograph.","indexable":true,"primary_intent":"toggle-guide","related":["switches","lp-controls","grounding-guide","lugs"],"tools":["signal","wiring"],"components":["potentiometers"],"published_at":"2026-10-05","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"A selector establishes connections"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"A conventional three-way guitar toggle selects one pickup, the other pickup or both. In the supported two-volume circuit, the selector inputs come from the volume wipers; its output continues to jack TIP. The centre position joins both channels to that output."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"This is a description of circuit function, not a universal physical pinout. Different toggle constructions can arrange solder tabs and ground contacts differently. Some switches present separate output contacts that must be joined as specified. Identify the exact part before copying a drawing."}]}]},{"type":"container","attrs":{"ref":"r5"},"content":[{"type":"heading","attrs":{"ref":"r6","level":2},"content":[{"type":"text","text":"Separate signal contacts from the frame"}]},{"type":"paragraph","attrs":{"ref":"r7"},"content":[{"type":"text","text":"The pickup inputs and common output are signal connections. A frame, shield or designated ground lug has a different role. Attaching a signal wire to a ground contact can mute the instrument, while omitting a required shield connection can leave noise problems."}]},{"type":"paragraph","attrs":{"ref":"r8"},"content":[{"type":"text","text":"For a braided pickup lead, the core and braid do different jobs. Colour-coded four-conductor pickups add coil starts, finishes and a separate shield where provided. Use the maker’s conductor convention to establish which lead is hot in the chosen series arrangement; colour alone is not a universal electrical identity."}]}]},{"type":"container","attrs":{"ref":"r9"},"content":[{"type":"heading","attrs":{"ref":"r10","level":2},"content":[{"type":"text","text":"Map the switch with continuity checks"}]},{"type":"paragraph","attrs":{"ref":"r11"},"content":[{"type":"text","text":"With the switch disconnected from the rest of the circuit, compare continuity between candidate inputs and outputs in each position. Record which input connects in the first position, which connects in the other end position and which contacts join in the centre. Verify the ground contact separately."}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"An in-circuit meter can see paths through pickups and pots, so a reading may not identify a switch contact cleanly. Isolate the switch when necessary. Establish the viewing orientation as well: a rear view and an installed player view can reverse apparent directions."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"Connect the functions, then route the wires"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"In the supported Les Paul reference, each volume output is lug 2. Those outputs go to the selector inputs, and the selector common goes to jack TIP. The jack sleeve connects to the return network. Follow the complete configured reference for both the signal and shielding paths."}]},{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"Physical wire routes can differ while the electrical connection remains equivalent. The important questions are which terminals are joined, which contacts close and whether an unintended short exists. Leave clearance for the switch movement, cavity cover and exposed solder tabs."}]}]},{"type":"container","attrs":{"ref":"r17"},"content":[{"type":"heading","attrs":{"ref":"r18","level":2},"content":[{"type":"text","text":"Distinguish a contact fault from a control interaction"}]},{"type":"paragraph","attrs":{"ref":"r19"},"content":[{"type":"text","text":"Intermittent output when the switch moves can point to contact condition or a stressed joint, but inspect the rest of the path before replacing the part. No output in one position can come from a disconnected pickup input, a channel fault or an incorrectly identified common."}]},{"type":"paragraph","attrs":{"ref":"r20"},"content":[{"type":"text","text":"Both pickups going silent when one volume reaches zero is consistent with the conventional dependent-volume arrangement. It should not automatically be blamed on the toggle. Test single-pickup positions and the shared output path to distinguish these cases."}]}]},{"type":"container","attrs":{"ref":"r21"},"content":[{"type":"heading","attrs":{"ref":"r22","level":2},"content":[{"type":"text","text":"Use a supported reference rather than inventing a pinout"}]},{"type":"paragraph","attrs":{"ref":"r23"},"content":[{"type":"text","text":"The Generator supplies a functional switch reference for its supported configurations. Compare it with the manufacturer’s physical contact drawing; it is not a claim that every aftermarket switch shares one mounting or terminal pattern. Signal Forge can help trace the selected path."}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"After assembly, inspect and check continuity before reconnecting equipment. A consistent contact map and labelled terminal functions are more useful than matching an unverified internet photograph. If the part does not match the reference, obtain its documentation instead of guessing."}]}]}]}}}}'::jsonb,'{"template_key":"toggle-guide","expected_intent":"toggle-guide","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"}},"slots":["main"]}'::jsonb),
('533497f6-a00a-5e41-a78a-641f7d56522e','grounding-guide','{"version":1,"title":"Guitar Grounding & Common Grounding Problems","slug":"guitar-grounding-common-problems","category":"wiring","intro":"Trace the signal return, shielding and jack sleeve systematically before replacing components to chase noise.","seo_title":"Guitar Grounding & Common Grounding Problems","meta_description":"Trace the signal return, shielding and jack sleeve systematically before replacing components to chase noise.","indexable":true,"primary_intent":"grounding-guide","related":["ground","toggle-guide","lugs","troubleshoot"],"tools":["signal","wiring"],"components":[],"published_at":"2026-10-05","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Ground is a circuit connection"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"In the supported passive guitar circuit, ground is the reference and return network for the signal. Volume lug 1, the designated control grounds and jack sleeve belong to that network. Jack TIP carries the output signal. A casing used as a solder point is not the pot’s wiper."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"A wire can look as though it reaches a casing without making a reliable electrical connection. Conversely, a different physical route can be electrically equivalent. Identify the intended nodes and verify continuity rather than relying on the appearance of the harness."}]}]},{"type":"container","attrs":{"ref":"r5"},"content":[{"type":"heading","attrs":{"ref":"r6","level":2},"content":[{"type":"text","text":"Shielding and signal return have different roles"}]},{"type":"paragraph","attrs":{"ref":"r7"},"content":[{"type":"text","text":"A shield intercepts unwanted electric-field coupling and is connected as specified for the instrument. Pickup shielding, cavity shielding and the signal return can meet at ground, but their purposes should still be identified. A bare shield is not automatically an available coil conductor."}]},{"type":"paragraph","attrs":{"ref":"r8"},"content":[{"type":"text","text":"Cavity shielding does not replace the pickup’s required electrical return. It also does not guarantee elimination of every type of hum: magnetic interference and the pickup’s construction matter. Avoid describing shielding material as a universal cure without identifying the noise mechanism."}]}]},{"type":"container","attrs":{"ref":"r9"},"content":[{"type":"heading","attrs":{"ref":"r10","level":2},"content":[{"type":"text","text":"Start outside the cavity"}]},{"type":"paragraph","attrs":{"ref":"r11"},"content":[{"type":"text","text":"Use a known-good cable and a consistent input before modifying the instrument. Check whether the problem follows one pickup selection, all selections or movement of the cable. A fault common to all positions can be in the jack or shared output path rather than inside every pickup channel."}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"Changes when touching strings can provide a clue about shielding and grounding, but they are not a complete diagnostic test. Record what changes and check the specified bridge/string ground where the circuit requires it. Some active systems have different requirements; follow their manufacturer’s instructions."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"Identify sleeve and TIP directly"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"Use the jack documentation and, where useful, an unconnected inserted plug to check which solder lug reaches TIP and which reaches sleeve. Apparent lug position is not a substitute for contact identity. A reversed or loose jack connection can create symptoms that look like a much larger wiring problem."}]},{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"Inspect for conductive parts touching the jack signal lug, stressed leads and rotation of the jack body. Secure mounting and adequate clearance matter. Work with the instrument disconnected; resistance readings made through attached equipment can be misleading."}]}]},{"type":"container","attrs":{"ref":"r17"},"content":[{"type":"heading","attrs":{"ref":"r18","level":2},"content":[{"type":"text","text":"Look for unintended signal-to-ground paths"}]},{"type":"paragraph","attrs":{"ref":"r19"},"content":[{"type":"text","text":"Check volume input lug 3 and wiper/output lug 2 for solder bridges to the casing or grounded lug 1. Inspect capacitor leads and selector tabs near grounded metal. A tone-loading branch belongs at its configured signal node, through the tone network toward ground; grounding the signal directly is a different connection."}]},{"type":"paragraph","attrs":{"ref":"r20"},"content":[{"type":"text","text":"Do not assume that every low resistance reading proves a short. Pickups and pot tracks provide legitimate paths, and connected branches affect a meter reading. Isolate a suspect section when needed and compare it with the intended connection list."}]}]},{"type":"container","attrs":{"ref":"r21"},"content":[{"type":"heading","attrs":{"ref":"r22","level":2},"content":[{"type":"text","text":"Change one thing after identifying the fault"}]},{"type":"paragraph","attrs":{"ref":"r23"},"content":[{"type":"text","text":"Establish the signal path and return path, inspect joints and then test the specific connection suggested by the symptom. Replacing parts without isolating the fault can add variables and leave the original problem in place. Keep a record of the exact configuration and terminal identities."}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"The Wiring Diagram Generator is a connection reference; it cannot inspect a physical joint or diagnose environmental interference. Never defeat equipment safety grounding to test a guitar noise theory. If a symptom points to external powered equipment, address that equipment through appropriate qualified service."}]}]}]}}}}'::jsonb,'{"template_key":"grounding-guide","expected_intent":"grounding-guide","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"}},"slots":["main"]}'::jsonb),
('187a45b9-7a4b-53de-a204-85ebcb1d9dcd','coil-split-guide','{"version":1,"title":"Coil Splitting Explained","slug":"coil-splitting-explained","category":"pickups","intro":"Understand what a split switch changes, how it differs from a coil tap and why conductor access and configuration limits matter.","seo_title":"Coil Splitting Explained","meta_description":"Understand what a split switch changes, how it differs from a coil tap and why conductor access and configuration limits matter.","indexable":true,"primary_intent":"coil-split-guide","related":["pickups","series-parallel-guide","lp-controls","toggle-guide","lugs","switches"],"tools":["signal","wiring"],"components":["potentiometers"],"published_at":"2026-10-05","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Begin with the two-coil series connection"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"A conventional series humbucker connects two coils through a series link. In the shared reference, the link joins the identified coil terminals while the signal and return use the remaining ends. A separate shield, where provided, retains its shielding connection."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"Access to that link is needed for the supported split arrangements. Four-conductor pickups commonly provide the necessary coil leads; a two-conductor construction may not expose them. Do not infer conductor function from a colour used by another manufacturer."}]}]},{"type":"container","attrs":{"ref":"r5"},"content":[{"type":"heading","attrs":{"ref":"r6","level":2},"content":[{"type":"text","text":"A split bypasses a coil in the supported arrangement"}]},{"type":"paragraph","attrs":{"ref":"r7"},"content":[{"type":"text","text":"The supported split switch connects the series-link node to ground in its split position, changing which coil contributes to the main output path. Its normal position preserves the series connection. The switch terminals and potentiometer terminals on a push-pull control are separate systems."}]},{"type":"paragraph","attrs":{"ref":"r8"},"content":[{"type":"text","text":"The selected active coil depends on the identified coil ends and the configuration. A generic statement that splitting always leaves the inner or outer coil active is unreliable without that information. Match the pickup documentation and the supported functional pinout before soldering."}]}]},{"type":"container","attrs":{"ref":"r9"},"content":[{"type":"heading","attrs":{"ref":"r10","level":2},"content":[{"type":"text","text":"Split, tap and parallel are different changes"}]},{"type":"paragraph","attrs":{"ref":"r11"},"content":[{"type":"text","text":"A split changes the participating coils in a multi-coil pickup circuit. A coil tap accesses another point in a winding and is a different construction feature. Parallel wiring keeps both coils connected in a different relationship; it is not another name for splitting."}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"These changes can alter output and frequency-dependent loading, but there is no universal volume loss or brightness figure for every pickup. The coil properties, pickup position, cable and controls matter. Do not attach a measured full-humbucker response curve to a split setting and call it a validated prediction."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"Do not assume the humbucking property survives"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"A conventional two-coil humbucker is designed to cancel particular common interference through its winding and magnetic arrangement. Using one coil changes that relationship. A split setting therefore should not be assumed to have the same interference rejection as the full series pickup."}]},{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"Combining split coils from two pickups can involve polarity, winding direction and which coils are selected. The fact that two coils are audible does not prove that their interference will cancel. Verify the intended arrangement instead of promising hum cancellation from a switch label."}]}]},{"type":"container","attrs":{"ref":"r17"},"content":[{"type":"heading","attrs":{"ref":"r18","level":2},"content":[{"type":"text","text":"Partial splits are another defined network"}]},{"type":"paragraph","attrs":{"ref":"r19"},"content":[{"type":"text","text":"Where the existing supported configuration provides a partial split, a resistor alters the series-link path to ground rather than simply making an ideal short. Its effect depends on the pickup and network. Treat it as a specific configured option, not a universal way to turn a humbucker into a particular single coil."}]},{"type":"paragraph","attrs":{"ref":"r20"},"content":[{"type":"text","text":"The Generator supports only its declared switch and pickup-access combinations. Some instruments use a shared split, others have separate controls. A push-pull knob’s position does not establish the electrical function until its switch contacts and wiring are known."}]}]},{"type":"container","attrs":{"ref":"r21"},"content":[{"type":"heading","attrs":{"ref":"r22","level":2},"content":[{"type":"text","text":"Inspect topology without overstating response capability"}]},{"type":"paragraph","attrs":{"ref":"r23"},"content":[{"type":"text","text":"Use the supported Generator reference for the configuration, conductor mapping and connection list. Signal Forge can explain supported conductive paths, but a validated coil-level response model is not supplied for split settings. The article adds no substitute electrical model."}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"Check series-link insulation, shield continuity and switch operation before reconnecting equipment. Compare the useful settings in the real instrument with the same cable and input. Choose a split because its available response and adjustment suit the job, not because the label promises a specific pickup identity."}]}]}]}}}}'::jsonb,'{"template_key":"coil-split-guide","expected_intent":"coil-split-guide","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"}},"slots":["main"]}'::jsonb),
('8004f5b4-1f85-5b5f-afe6-9df0a0e6ef06','series-parallel-guide','{"version":1,"title":"Series vs Parallel Pickup Wiring","slug":"series-vs-parallel-pickup-wiring","category":"pickups","intro":"Separate coil connections inside a pickup from connections between pickups, and understand the limits of a conceptual comparison.","seo_title":"Series vs Parallel Pickup Wiring","meta_description":"Separate coil connections inside a pickup from connections between pickups, and understand the limits of a conceptual comparison.","indexable":true,"primary_intent":"series-parallel-guide","related":["coil-split-guide","pickups","lp-controls","toggle-guide"],"tools":["signal","wiring"],"components":["potentiometers"],"published_at":"2026-10-05","content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"First identify what is being connected"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"Series and parallel describe relationships between circuit elements. They can refer to the coils inside one humbucker or to two complete pickups. Those are different changes, so a wiring description should say which elements are involved before discussing the result."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"The shared conventional humbucker reference uses a series link between two coils. The supported Les Paul both-pickup position joins two pickup-channel outputs at the selector. Calling both situations a two-coil sound hides the different connections and their control interactions."}]}]},{"type":"container","attrs":{"ref":"r5"},"content":[{"type":"heading","attrs":{"ref":"r6","level":2},"content":[{"type":"text","text":"Series coils share a signal path"}]},{"type":"paragraph","attrs":{"ref":"r7"},"content":[{"type":"text","text":"In a series connection, the path continues through one coil and then the other. The winding impedances contribute to the complete frequency-dependent source. The shared series-link reference identifies the coil junction separately from the final signal and return leads."}]},{"type":"paragraph","attrs":{"ref":"r8"},"content":[{"type":"text","text":"Signal voltages can reinforce or oppose one another according to winding and magnetic relationships. Therefore a simple component-count rule does not guarantee a particular output. The source impedance, connected load and pickup construction remain part of the result."}]}]},{"type":"container","attrs":{"ref":"r9"},"content":[{"type":"heading","attrs":{"ref":"r10","level":2},"content":[{"type":"text","text":"Parallel is a different connection, not a split"}]},{"type":"paragraph","attrs":{"ref":"r11"},"content":[{"type":"text","text":"In a conceptual parallel arrangement, both coils remain connected across common nodes rather than one following the other in a single series path. This changes the source relationship and its interaction with the load. It is different from a split, which changes coil participation in the supported split network."}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"This guide does not provide a new parallel terminal recipe. The inspected shared Generator establishes the series and supported split references, but does not supply a general parallel-coil switching pinout. Use an authoritative pickup-specific drawing for that modification instead of adapting a series-link picture by guesswork."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"Two pickups introduce additional controls"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"Two complete pickup channels joined by a selector have their own impedances and, in a Les Paul-style harness, their own volume and tone networks. In the conventional combined position the volume outputs share a node. Turning one control fully down can ground that node and mute the combination."}]},{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"That interaction is not the same as connecting two isolated coils in parallel inside one pickup. A diagram must include the surrounding controls before its behaviour can be assessed. The present single-pickup response model does not validate the combined-pickup response."}]}]},{"type":"container","attrs":{"ref":"r17"},"content":[{"type":"heading","attrs":{"ref":"r18","level":2},"content":[{"type":"text","text":"Explain the change without a universal tone promise"}]},{"type":"paragraph","attrs":{"ref":"r19"},"content":[{"type":"text","text":"Players often describe a parallel option as having a different level or tonal balance from a series option. Those descriptions are useful observations from a particular instrument, not fixed specifications for every humbucker. Coil inductance, resistance, coupling and the external load affect the electrical response."}]},{"type":"paragraph","attrs":{"ref":"r20"},"content":[{"type":"text","text":"Keeping two coils active does not by itself prove noise cancellation. Winding direction, magnetic polarity and signal orientation matter. Keep shield identity separate from coil leads; a shielding conductor is not an extra coil terminal available for a switching experiment."}]}]},{"type":"container","attrs":{"ref":"r21"},"content":[{"type":"heading","attrs":{"ref":"r22","level":2},"content":[{"type":"text","text":"Use the right authority for the proposed modification"}]},{"type":"paragraph","attrs":{"ref":"r23"},"content":[{"type":"text","text":"Before choosing a switching option, identify the pickup’s exposed coil leads, the intended control and an authoritative connection reference. The existing tools can continue with the supported series/split configurations; this explanatory comparison does not claim additional Generator capability."}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"For a practical comparison, keep the cable, amplifier input and other controls consistent and document each setting. If no verified connection drawing exists for the desired topology, defer the modification. Understanding a circuit distinction is useful even when the safe next step is to obtain the correct part documentation."}]}]}]}}}}'::jsonb,'{"template_key":"series-parallel-guide","expected_intent":"series-parallel-guide","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"}},"slots":["main"]}'::jsonb),
('9791e7b8-752b-5844-a75e-141a60cfe11f','caps','{"version":1,"title":"Capacitors and Treble Bleeds Explained","slug":"capacitors-treble-bleeds","category":"tone-controls","intro":"Capacitors perform two different jobs depending on where they are used. In a tone circuit they form a frequency-dependent path to ground. Across a volume control they can form part of a treble bleed circuit.","seo_title":"Guitar Capacitors: Units, Types & Specifications","meta_description":"Read capacitor units, tolerance, construction and physical specifications. For choosing 0.022 versus 0.047 µF, continue to the dedicated value comparison.","indexable":true,"primary_intent":null,"related":["pots","lugs"],"tools":["signal"],"components":["capacitors"],"published_at":null,"content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Tone capacitors"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"A capacitor’s opposition to alternating current decreases as frequency rises. In a guitar tone branch, the capacitor and tone potentiometer allow higher-frequency signal to reach ground more readily than lower-frequency signal. This is a branch off the signal path, not a component every part of the output must pass through."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"As the tone control is rolled down, increasing capacitance generally extends the effect further into lower frequencies. The pickup’s inductance, pot resistance and other loads mean the result is more involved than a single fixed cutoff frequency."}]},{"type":"container","attrs":{"ref":"r5"},"content":[{"type":"protected","attrs":{"ref":"r6"}}]},{"type":"paragraph","attrs":{"ref":"r7"},"content":[{"type":"text","text":"These are starting points, not a quality ranking. Compare values with your actual pickups and how far you use the tone control. A value useful on one guitar may be excessive or too subtle on another."}]},{"type":"protected","attrs":{"ref":"r8"}}]},{"type":"container","attrs":{"ref":"r9"},"content":[{"type":"heading","attrs":{"ref":"r10","level":2},"content":[{"type":"text","text":"Capacitor construction"}]},{"type":"paragraph","attrs":{"ref":"r11"},"content":[{"type":"text","text":"Polyester film, polypropylene film and ceramic capacitors use different dielectric materials and constructions. Their specifications can differ in tolerance, stability, temperature behaviour and physical size. A voltage rating describes an operating limit, not an extra amount of “tone”."}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"Apparition focuses on correct capacitance, appropriate tolerance, measured value, reliable construction and a part that fits the cavity. Brand or price alone is not evidence of an audible benefit. Compare the actual specifications before assuming two capacitors with the same printed value behave differently in your guitar."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"What is a treble bleed?"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"Rolling down a passive guitar’s volume can change the interaction between the pickup, volume pot and cable capacitance, often reducing high-frequency content. A treble bleed provides a frequency-dependent bypass between the volume control’s input and output."}]},{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"Both "},{"type":"text","text":"Fender","marks":[{"type":"link","attrs":{"href":"https://www.fender.com/articles/maintenance/how-a-treble-bleed-circuit-can-affect-your-tone"}}]},{"type":"text","text":" and "},{"type":"text","text":"Seymour Duncan","marks":[{"type":"link","attrs":{"href":"https://www.seymourduncan.com/blog/latest-updates/3-popular-treble-bleed-mods-what-you-need-to-know"}}]},{"type":"text","text":" describe circuits intended to retain more high-frequency content as volume is reduced. It is an optional response change, not a repair every guitar needs."}]}]},{"type":"container","attrs":{"ref":"r17"},"content":[{"type":"heading","attrs":{"ref":"r18","level":2},"content":[{"type":"text","text":"Capacitor-only arrangements"}]},{"type":"paragraph","attrs":{"ref":"r19"},"content":[{"type":"text","text":"The simplest arrangement places a capacitor between volume input and wiper. Apparition’s examples are the 180pF PRS-style Treble Bleed and the 1nF Capacitor-only Treble Bleed. 1nF equals 0.001µF or 1,000pF."}]},{"type":"paragraph","attrs":{"ref":"r20"},"content":[{"type":"text","text":"The larger value passes more lower-frequency content through the bypass at a given impedance, but that does not make it better. The effect depends on the pot setting and surrounding circuit. At full volume the input and wiper are already very close electrically, so the bypass has little voltage across it."}]},{"type":"paragraph","attrs":{"ref":"r21"},"content":[{"type":"text","text":"View the 180pF example →","marks":[{"type":"link","attrs":{"href":"/wiring-generator/?g=%7B%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22prs%22%7D"}}]}]}]},{"type":"container","attrs":{"ref":"r22"},"content":[{"type":"heading","attrs":{"ref":"r23","level":2},"content":[{"type":"text","text":"Capacitor and resistor in parallel"}]},{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"The 1nF + 150kΩ Duncan-style Treble Bleed connects a capacitor and resistor across the same two volume terminals. Parallel means both component ends share the corresponding input and output connections. The resistor provides a non-frequency-selective path alongside the capacitor and changes the volume control’s effective response and taper."}]},{"type":"paragraph","attrs":{"ref":"r25"},"content":[{"type":"text","text":"Do not confuse this with a capacitor and resistor in series. Their electrical behaviour is different. In a two-volume Apparition kit, the chosen bleed configuration is fitted to both volume controls."}]},{"type":"paragraph","attrs":{"ref":"r26"},"content":[{"type":"text","text":"View the parallel network →","marks":[{"type":"link","attrs":{"href":"/wiring-generator/?g=%7B%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22duncan%22%7D"}}]}]}]},{"type":"container","attrs":{"ref":"r27"},"content":[{"type":"heading","attrs":{"ref":"r28","level":2},"content":[{"type":"text","text":"Which should I choose?"}]},{"type":"paragraph","attrs":{"ref":"r29"},"content":[{"type":"text","text":"Consider your pickup, pot value, cable capacitance, wiring circuit, volume-control habits and personal preference. If you like the way your guitar loses high end as you reduce volume, you may prefer no treble bleed. If you rely on a clearer reduced-volume sound, a bleed is worth comparing."}]},{"type":"paragraph","attrs":{"ref":"r30"},"content":[{"type":"text","text":"Our generator offers standard treble bleeds with Modern and 60s Les Paul wiring. It disables them for its 50s preset, where the tone branch already follows the volume output. This is the supported Apparition configuration, not a claim that every other circuit combination is physically impossible."}]},{"type":"paragraph","attrs":{"ref":"r31"},"content":[{"type":"text","text":"Use the links below to compare the actual connections. The diagram explains topology; it does not simulate what your particular guitar will sound like."}]},{"type":"protected","attrs":{"ref":"r32"}}]},{"type":"container","attrs":{"ref":"r33"},"content":[{"type":"heading","attrs":{"ref":"r34","level":2},"content":[{"type":"text","text":"Values and units"}]},{"type":"paragraph","attrs":{"ref":"r35"},"content":[{"type":"text","text":"1 µF = 1,000 nF = 1,000,000 pF. Common guitar tone values include 0.010, 0.015, 0.022, 0.033 and 0.047 µF, equivalent to 10, 15, 22, 33 and 47 nF. Compare supported values with the tone control position held constant. Tolerance changes the actual capacitance. The voltage rating is a permissible working limit, not a promise of a different guitar response. A large high-voltage part and a small part can have the same capacitance; dielectric, leakage, reliability and physical fit are specifications to consider without assuming an audible benefit from size or brand."}]}]},{"type":"protected","attrs":{"ref":"r36"}}]}}}}'::jsonb,'{"template_key":"caps","expected_intent":null,"refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"protected"},"r7":{"kind":"node"},"r8":{"kind":"protected"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"},"r25":{"kind":"node"},"r26":{"kind":"node"},"r27":{"kind":"node"},"r28":{"kind":"node"},"r29":{"kind":"node"},"r30":{"kind":"node"},"r31":{"kind":"node"},"r32":{"kind":"protected"},"r33":{"kind":"node"},"r34":{"kind":"node"},"r35":{"kind":"node"},"r36":{"kind":"protected"}},"slots":["main"]}'::jsonb),
('91121376-fcdd-5897-a1cb-af6337f2d914','pickups','{"version":1,"title":"Pickup conductors and colour conventions","slug":"pickup-conductors","category":"pickups","intro":"Separate coil function from wire colour before making a connection.","seo_title":"Pickup conductors and colour conventions","meta_description":"Separate coil function from wire colour before making a connection.","indexable":true,"primary_intent":null,"related":["pots","lugs","coil-split-guide","series-parallel-guide"],"tools":["wiring"],"components":[],"published_at":null,"content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"One conductor, two conductors and braid"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"A single insulated core with an outer braid commonly uses the core for signal and the braid as the return and shield. Two insulated conductors can provide separate signal and return, sometimes with an additional shield. Identify your exact construction from the pickup maker’s documentation."}]}]},{"type":"container","attrs":{"ref":"r4"},"content":[{"type":"heading","attrs":{"ref":"r5","level":2},"content":[{"type":"text","text":"Four conductors and coil ends"}]},{"type":"paragraph","attrs":{"ref":"r6"},"content":[{"type":"text","text":"A four-conductor humbucker exposes the start and finish of each coil, allowing a normal series connection to be identified. The shared wiring authority names coil functions independently of colour. Coil start and finish are winding references; they do not independently establish magnetic polarity or a complete phase relationship."}]}]},{"type":"container","attrs":{"ref":"r7"},"content":[{"type":"heading","attrs":{"ref":"r8","level":2},"content":[{"type":"text","text":"Series link, hot and return"}]},{"type":"paragraph","attrs":{"ref":"r9"},"content":[{"type":"text","text":"In the supported standard series humbucker, two coil ends form the local series link and are insulated together. The remaining signal lead goes to the volume input; the coil return and separate shield terminate at the authorised ground point. The series link is not a ground connection."}]}]},{"type":"container","attrs":{"ref":"r10"},"content":[{"type":"heading","attrs":{"ref":"r11","level":2},"content":[{"type":"text","text":"Manufacturer colours are conventions"}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"The reference below is rendered from the same pickupConventions registry used by the Generator and Forge. Unresolved profiles show semantic functions rather than invented colours. Check the exact pickup model and manufacturer instructions before relying on a convention."}]},{"type":"protected","attrs":{"ref":"r13"}}]},{"type":"container","attrs":{"ref":"r14"},"content":[{"type":"heading","attrs":{"ref":"r15","level":2},"content":[{"type":"text","text":"What these colours do not tell you"}]},{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"Colour mappings do not supply measured pickup resistance, inductance or capacitance. Signal Lab presets are illustrative electrical assumptions. Coil split, phase and series/parallel response modelling are deferred."}]}]},{"type":"container","attrs":{"ref":"r17"},"content":[{"type":"protected","attrs":{"ref":"r18"}}]}]}}}}'::jsonb,'{"template_key":"pickups","expected_intent":null,"refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"protected"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"protected"}},"slots":["main"]}'::jsonb),
('bb215f65-4c29-589b-ac50-ce467e92e8fc','switches','{"version":1,"title":"Selector contacts and pickup paths","slug":"selectors","category":"pickups","intro":"A selector connects terminals. Its physical layout must match the circuit you are wiring.","seo_title":"Guitar Switches: Contact & Selector Reference","meta_description":"Identify switch contacts and selector concepts before transferring a circuit to a physical part. Use the dedicated toggle guide for the supported three-way wiring route.","indexable":true,"primary_intent":null,"related":["pots","lugs","toggle-guide"],"tools":["signal"],"components":[],"published_at":null,"content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Open and closed contacts"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"A closed contact provides a conductive path between terminals. An open contact interrupts that path. A selector is a set of these connections, not an electronic mixer with its own gain."}]}]},{"type":"container","attrs":{"ref":"r4"},"content":[{"type":"heading","attrs":{"ref":"r5","level":2},"content":[{"type":"text","text":"The supported three-way circuit"}]},{"type":"paragraph","attrs":{"ref":"r6"},"content":[{"type":"text","text":"In the shared Les Paul topology, Neck connects the neck volume output to the common output, Bridge connects the bridge volume output, and Both connects both branches. Circuit Lab shows the actual closed contacts and traces to the jack. Connecting Both physically does not mean Signal Lab has a validated coupled response model."}]}]},{"type":"container","attrs":{"ref":"r7"},"content":[{"type":"heading","attrs":{"ref":"r8","level":2},"content":[{"type":"text","text":"Identify terminals before soldering"}]},{"type":"paragraph","attrs":{"ref":"r9"},"content":[{"type":"text","text":"Common means the shared output contact in this context. Switch terminal positions vary by construction. Use the exact switch specification and a continuity test with the guitar disconnected; do not infer terminal function from its location alone."}]}]},{"type":"container","attrs":{"ref":"r10"},"content":[{"type":"heading","attrs":{"ref":"r11","level":2},"content":[{"type":"text","text":"Use the right tool"}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"Circuit Lab explains paths and contacts. Wiring Generator presents physical destinations. More complex switch topology and coil-level response are not added by this guide."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"protected","attrs":{"ref":"r14"}}]}]}}}}'::jsonb,'{"template_key":"switches","expected_intent":null,"refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"protected"}},"slots":["main"]}'::jsonb),
('82dccc6f-04bd-520f-abe4-c386613fc4cf','circuits','{"version":1,"title":"Guitar Wiring Circuits Explained","slug":"wiring-circuits-explained","category":"wiring","intro":"A passive guitar circuit is easier to understand when you stop looking at it as a mass of wires and start following the signal from one component to the next.","seo_title":"Guitar wiring circuits explained","meta_description":"Follow the signal, understand the controls and compare supported passive wiring.","indexable":true,"primary_intent":"circuits","related":["pots","lugs","modern-50s","lp-controls"],"tools":["signal"],"components":[],"published_at":null,"content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Start with the signal path"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"Pickup → Output Jack.","marks":[{"type":"strong"}]},{"type":"text","text":" A pickup can connect directly to an output, with a hot lead to tip and its return to sleeve. Controls add useful ways to adjust or choose that signal."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"Pickup → Volume → Output.","marks":[{"type":"strong"}]},{"type":"text","text":" A volume control adds a variable signal divider. "},{"type":"text","text":"Pickup → Volume + Tone → Output.","marks":[{"type":"strong"}]},{"type":"text","text":" The tone network adds a branch to ground; it is not in series with the entire output."}]},{"type":"paragraph","attrs":{"ref":"r5"},"content":[{"type":"text","text":"Pickups → Controls → Selector → Output.","marks":[{"type":"strong"}]},{"type":"text","text":" This describes a traditional Les Paul arrangement. In master-volume circuits such as a Strat or Tele, the selector normally comes before the master volume. There is no single component order for every guitar."}]},{"type":"protected","attrs":{"ref":"r6"}}]},{"type":"container","attrs":{"ref":"r7"},"content":[{"type":"heading","attrs":{"ref":"r8","level":2},"content":[{"type":"text","text":"Signal and ground"}]},{"type":"paragraph","attrs":{"ref":"r9"},"content":[{"type":"text","text":"Hot or signal connections carry the pickup signal towards the output. Ground is the shared return/reference network connected to the jack sleeve. Pickup returns, pot casings, switch frames, shielding and the bridge/string ground belong to this network where specified by the circuit."}]},{"type":"paragraph","attrs":{"ref":"r10"},"content":[{"type":"text","text":"A wire crossing another wire in the generator does not make a connection. Only the labelled terminal circles mark junctions. Selecting a wire traces its connected wiring and closed switch contacts, rather than pretending to simulate every current path through resistive components."}]}]},{"type":"container","attrs":{"ref":"r11"},"content":[{"type":"heading","attrs":{"ref":"r12","level":2},"content":[{"type":"text","text":"Volume and tone"}]},{"type":"paragraph","attrs":{"ref":"r13"},"content":[{"type":"text","text":"A standard volume uses lug 3 for input, lug 1 for ground and lug 2, the movable wiper, for output. Turn the shaft and the wiper moves along the resistive track. Our rear-view drawings number the downward-facing lugs 3–2–1 from left to right."}]},{"type":"paragraph","attrs":{"ref":"r14"},"content":[{"type":"text","text":"The tone pot and capacitor provide a variable frequency-dependent path to ground. The capacitor value sets part of that response; the pot controls the branch resistance. The casing ground and resistive-track terminals are separate connections."}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"Understand potentiometers →","marks":[{"type":"link","attrs":{"href":"/luthier-hub/potentiometers-explained/"}}]},{"type":"text","text":"Understand capacitors →","marks":[{"type":"link","attrs":{"href":"/luthier-hub/capacitors-treble-bleeds/"}}]}]}]},{"type":"container","attrs":{"ref":"r16"},"content":[{"type":"heading","attrs":{"ref":"r17","level":2},"content":[{"type":"text","text":"Selector and output jack"}]},{"type":"paragraph","attrs":{"ref":"r18"},"content":[{"type":"text","text":"A pickup selector connects chosen inputs to an output or other circuit nodes. A blade’s poles are separate switching sections; throws are the contacts selected as the lever moves. A five-way Strat switch can connect adjacent pickup contacts in the in-between positions."}]},{"type":"paragraph","attrs":{"ref":"r19"},"content":[{"type":"text","text":"A conventional passive mono output jack uses Tip for signal and Sleeve for common ground. Check with an unplugged cable and a meter to identify the contacts. A contact’s visual position is not enough: jack and switch constructions vary."}]}]},{"type":"container","attrs":{"ref":"r20"},"content":[{"type":"heading","attrs":{"ref":"r21","level":2},"content":[{"type":"text","text":"Multiple pickups and control arrangements"}]},{"type":"paragraph","attrs":{"ref":"r22"},"content":[{"type":"text","text":"A master volume adjusts the selected pickup combination. Separate volumes allow individual adjustment, but the wiring matters: in the traditional Les Paul circuit shown here, turning either volume fully down in the Both position also mutes the combined output. “Independent controls” should not be assumed from the number of knobs."}]},{"type":"paragraph","attrs":{"ref":"r23"},"content":[{"type":"text","text":"Our classic SSS Strat has a master volume, separate neck and middle tones, and no bridge tone. The Tele preset has master volume and tone. The supported PRS-style superswitch conversion has two humbuckers, master controls and defined split-coil combinations. It is not a universal factory PRS diagram."}]},{"type":"protected","attrs":{"ref":"r24"}}]},{"type":"container","attrs":{"ref":"r25"},"content":[{"type":"heading","attrs":{"ref":"r26","level":2},"content":[{"type":"text","text":"Modern, 50s and 60s Les Paul wiring"}]},{"type":"paragraph","attrs":{"ref":"r27"},"content":[{"type":"text","text":"The principal Modern/50s difference is where the tone branch leaves the volume pot. Modern connects it to the input at lug 3. The 50s preset connects it to the output/wiper at lug 2, so the tone network interacts differently as volume changes."}]},{"type":"paragraph","attrs":{"ref":"r28"},"content":[{"type":"text","text":"Our 60s preset takes the branch from the volume input and grounds the tone wiper. The generator shows each exact connection, including which tone lug is grounded. These names can be used inconsistently elsewhere; inspect the drawing rather than relying on a label alone. None is universally superior."}]},{"type":"protected","attrs":{"ref":"r29"}}]},{"type":"container","attrs":{"ref":"r30"},"content":[{"type":"heading","attrs":{"ref":"r31","level":2},"content":[{"type":"text","text":"Treble bleeds and coil splitting"}]},{"type":"paragraph","attrs":{"ref":"r32"},"content":[{"type":"text","text":"A treble bleed belongs across a volume control’s input and output. Its capacitor, sometimes paired with a resistor, changes what passes around the volume track as it is turned down."}]},{"type":"paragraph","attrs":{"ref":"r33"},"content":[{"type":"text","text":"A four-conductor humbucker brings out the ends of both coils. Joining two conductors makes the usual series junction. A coil split uses switching to bypass one coil. A partial split places resistance in that bypass so the coil is not shunted as completely. Values and coil choices depend on the verified circuit; do not copy them by colour from a different pickup brand."}]},{"type":"paragraph","attrs":{"ref":"r34"},"content":[{"type":"text","text":"A split humbucker generally loses its normal hum-cancelling operation. “Coil tap” is a different construction feature and is not another name for coil splitting."}]},{"type":"paragraph","attrs":{"ref":"r35"},"content":[{"type":"text","text":"Read about treble bleeds →","marks":[{"type":"link","attrs":{"href":"/luthier-hub/capacitors-treble-bleeds/"}}]}]}]},{"type":"container","attrs":{"ref":"r36"},"content":[{"type":"heading","attrs":{"ref":"r37","level":2},"content":[{"type":"text","text":"Series, parallel and phase"}]},{"type":"paragraph","attrs":{"ref":"r38"},"content":[{"type":"text","text":"Series connects components end-to-end; parallel connects them across shared nodes. Two humbucker coils are commonly in series internally, while two selected guitar pickups are commonly combined in parallel. Changing these arrangements changes the combined impedance and output."}]},{"type":"paragraph","attrs":{"ref":"r39"},"content":[{"type":"text","text":"Phase reversal changes one pickup’s electrical polarity relative to another and is mainly heard when they are combined. It is not the same as selecting a different coil. Keep a separate shield grounded; do not repurpose a grounded cover or bare shield as a hot connection."}]},{"type":"paragraph","attrs":{"ref":"r40"},"content":[{"type":"text","text":"Advanced switching must match the available conductors and switch contacts. Unsupported modifications remain unavailable until their circuit is checked."}]},{"type":"paragraph","attrs":{"ref":"r41"},"content":[{"type":"text","text":"Explore with the Wiring Diagram Generator →","marks":[{"type":"link","attrs":{"href":"/wiring-generator/"}}]}]}]},{"type":"protected","attrs":{"ref":"r42"}}]}}}}'::jsonb,'{"template_key":"circuits","expected_intent":"circuits","refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"protected"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"node"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"protected"},"r25":{"kind":"node"},"r26":{"kind":"node"},"r27":{"kind":"node"},"r28":{"kind":"node"},"r29":{"kind":"protected"},"r30":{"kind":"node"},"r31":{"kind":"node"},"r32":{"kind":"node"},"r33":{"kind":"node"},"r34":{"kind":"node"},"r35":{"kind":"node"},"r36":{"kind":"node"},"r37":{"kind":"node"},"r38":{"kind":"node"},"r39":{"kind":"node"},"r40":{"kind":"node"},"r41":{"kind":"node"},"r42":{"kind":"protected"}},"slots":["main"]}'::jsonb),
('e068bad6-b59b-572a-a62e-5aed396fc178','ground','{"version":1,"title":"Ground, shield and the output jack","slug":"grounding-output","category":"wiring","intro":"Follow the signal return and keep shielding roles clear.","seo_title":"Guitar Ground, Shield & Output Jack Reference","meta_description":"Identify signal return, shield and jack TIP/sleeve functions. For a fault-finding sequence, continue to the guitar grounding problems guide.","indexable":true,"primary_intent":null,"related":["pots","lugs","grounding-guide"],"tools":["wiring"],"components":[],"published_at":null,"content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Signal ground and output"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"Signal ground is the circuit’s reference and return path. The output jack sleeve connects to that return; the tip carries the output signal. Identify tip and sleeve contacts on the actual jack, rather than using their apparent position."}]}]},{"type":"container","attrs":{"ref":"r4"},"content":[{"type":"heading","attrs":{"ref":"r5","level":2},"content":[{"type":"text","text":"Pot casings and shared return"}]},{"type":"paragraph","attrs":{"ref":"r6"},"content":[{"type":"text","text":"The supported wiring uses authorised casing solder points and a shared ground harness. A grounded lug is a separate electrical connection from the metal casing. Check each required bond and the final sleeve connection."}]}]},{"type":"container","attrs":{"ref":"r7"},"content":[{"type":"heading","attrs":{"ref":"r8","level":2},"content":[{"type":"text","text":"Ground is a node; shielding is a role"}]},{"type":"paragraph","attrs":{"ref":"r9"},"content":[{"type":"text","text":"A shield or drain conductor can connect to the ground reference while its purpose is to reduce interference reaching the signal wiring. Coil return and shield are separately identified even when they terminate at one casing point. A shield is not an interchangeable signal lead."}]}]},{"type":"container","attrs":{"ref":"r10"},"content":[{"type":"heading","attrs":{"ref":"r11","level":2},"content":[{"type":"text","text":"Bridge and string ground"}]},{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"Where the instrument design requires it, the bridge/string bond connects the metal hardware to the guitar’s ground network. Touching grounded strings can change picked-up interference; it does not by itself prove the entire wiring is correct."}]}]},{"type":"container","attrs":{"ref":"r13"},"content":[{"type":"heading","attrs":{"ref":"r14","level":2},"content":[{"type":"text","text":"Check continuity safely"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"Disconnect the guitar from the amplifier before resistance or continuity checks. Compare the intended ground points with jack sleeve, and inspect for loose joints or shorts to hot terminals. A continuity reading alone does not diagnose every intermittent fault. This guide concerns passive guitars; do not open mains-powered amplifier equipment."}]}]},{"type":"container","attrs":{"ref":"r16"},"content":[{"type":"protected","attrs":{"ref":"r17"}}]}]}}}}'::jsonb,'{"template_key":"ground","expected_intent":null,"refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"protected"}},"slots":["main"]}'::jsonb),
('3d9523fa-00cd-5c19-ac85-89251f63e763','install','{"version":1,"title":"How to Wire a Les Paul Using an Apparition Kit","slug":"les-paul-installation","category":"wiring","intro":"A practical guide to fitting a passive two-volume, two-tone harness. Use the diagram for your selected kit and verify the actual hardware before making connections.","seo_title":"Wire a Les Paul using your kit","meta_description":"Prepare, connect, inspect and test against the diagram for your supported configuration.","indexable":true,"primary_intent":null,"related":["pots","lugs"],"tools":["wiring"],"components":[],"published_at":null,"content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"container","attrs":{"ref":"r1"},"content":[{"type":"heading","attrs":{"ref":"r2","level":2},"content":[{"type":"text","text":"Before you start"}]},{"type":"paragraph","attrs":{"ref":"r3"},"content":[{"type":"text","text":"Soldering equipment becomes extremely hot. Work on a heat-resistant surface with ventilation and eye protection, keep the iron in its stand and protect the guitar finish. Disconnect the guitar from the amplifier and any power source. Only undertake work you are comfortable performing; ask a qualified guitar technician if you are unsure."}]},{"type":"paragraph","attrs":{"ref":"r4"},"content":[{"type":"text","text":"Photograph the original wiring from several angles and label each wire before removing anything. Identify the pickups and their exact conductor convention. Confirm shaft/bushing length, diameter, knob fit, cavity depth and control spacing. A Les Paul-style model name alone does not confirm compatibility."}]},{"type":"paragraph","attrs":{"ref":"r5"},"content":[{"type":"text","text":"Prepare a clean, well-lit workspace and a padded support that does not react with the finish. Keep solder and hot tools away from the instrument surface. This guide covers the supported passive harness; active pickups and additional switching need their own instructions."}]}]},{"type":"container","attrs":{"ref":"r6"},"content":[{"type":"heading","attrs":{"ref":"r7","level":2},"content":[{"type":"text","text":"Tools"}]},{"type":"bullet_list","attrs":{"ref":"r8"},"content":[{"type":"list_item","attrs":{"ref":"r9"},"content":[{"type":"paragraph","attrs":{"ref":"r10"},"content":[{"type":"text","text":"Temperature-controlled soldering iron and appropriate electronics solder"}]}]},{"type":"list_item","attrs":{"ref":"r11"},"content":[{"type":"paragraph","attrs":{"ref":"r12"},"content":[{"type":"text","text":"Wire cutters, suitable wire strippers and small pliers"}]}]},{"type":"list_item","attrs":{"ref":"r13"},"content":[{"type":"paragraph","attrs":{"ref":"r14"},"content":[{"type":"text","text":"Nut drivers or spanners matching the hardware"}]}]},{"type":"list_item","attrs":{"ref":"r15"},"content":[{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"Multimeter and a known-good guitar cable"}]}]},{"type":"list_item","attrs":{"ref":"r17"},"content":[{"type":"paragraph","attrs":{"ref":"r18"},"content":[{"type":"text","text":"Heat-resistant working surface, suitable finish protection and ventilation"}]}]}]},{"type":"paragraph","attrs":{"ref":"r19"},"content":[{"type":"text","text":"Use tools sized for the job. Do not use acid-core plumbing solder. Set up the iron according to the tool, solder and component guidance; excessive heating can damage pots, insulation and the guitar finish."}]}]},{"type":"protected","attrs":{"ref":"r20"}},{"type":"container","attrs":{"ref":"r21"},"content":[{"type":"heading","attrs":{"ref":"r22","level":2},"content":[{"type":"text","text":"Step 1 / Identify the circuit"}]},{"type":"container","attrs":{"ref":"r23"},"content":[{"type":"paragraph","attrs":{"ref":"r24"},"content":[{"type":"text","text":"No saved kit has been opened with this guide. Configure your kit or choose the matching circuit before soldering."}]}]},{"type":"paragraph","attrs":{"ref":"r25"},"content":[{"type":"text","text":"Open your selected diagram and check wiring style, capacitor values, treble bleeds and supplied hardware. The diagram includes existing pickups, grounds and any jack or selector you are retaining. “Existing / Not included” means electrically required but not newly supplied."}]},{"type":"paragraph","attrs":{"ref":"r26"},"content":[{"type":"text","text":"Open your wiring diagram →","marks":[{"type":"link","attrs":{"href":"/wiring-generator/"}}]}]}]},{"type":"container","attrs":{"ref":"r27"},"content":[{"type":"heading","attrs":{"ref":"r28","level":2},"content":[{"type":"text","text":"Step 2 / Remove the existing controls"}]},{"type":"paragraph","attrs":{"ref":"r29"},"content":[{"type":"text","text":"Loosen or remove strings only as needed for safe access. Remove cavity covers or other access parts carefully and retain screws. Identify every connection before desoldering it, and preserve sufficient usable lead length. Support a potentiometer or jack while loosening its nut so it cannot twist and pull wires."}]},{"type":"paragraph","attrs":{"ref":"r30"},"content":[{"type":"text","text":"Construction differs between guitars. Do not assume a control can pass through an opening or that a connector, mounting hole or cavity is compatible. Stop if removal requires unexpected force."}]}]},{"type":"container","attrs":{"ref":"r31"},"content":[{"type":"heading","attrs":{"ref":"r32","level":2},"content":[{"type":"text","text":"Step 3 / Install the potentiometers"}]},{"type":"paragraph","attrs":{"ref":"r33"},"content":[{"type":"text","text":"Test the harness fit before soldering the external connections. Orient the pots so terminals and capacitors have clearance from cavity walls, shielding and covers. Use the appropriate washers and nuts, support each component and tighten only enough to secure it. Avoid twisting the assembled harness."}]},{"type":"paragraph","attrs":{"ref":"r34"},"content":[{"type":"text","text":"Do not force shafts or incompatible knobs, overtighten mounting nuts or bend capacitor leads sharply at the body. Check that the control cavity closes without pressing on components."}]}]},{"type":"container","attrs":{"ref":"r35"},"content":[{"type":"heading","attrs":{"ref":"r36","level":2},"content":[{"type":"text","text":"Step 4 / Connect pickups"}]},{"type":"paragraph","attrs":{"ref":"r37"},"content":[{"type":"text","text":"Follow the generated pickup-hot and ground connections. Verify your exact manufacturer/model wiring convention before soldering. The Generator’s colour selector identifies which conventions are verified; an unverified choice uses functional generic labels, not guessed colours."}]},{"type":"paragraph","attrs":{"ref":"r38"},"content":[{"type":"text","text":"For a standard series humbucker, join and insulate the designated series-link wires as shown. Keep the bare shield on ground. A braided two-conductor pickup does not provide separate access to both coil ends and cannot be treated as a four-conductor pickup for splitting."}]}]},{"type":"container","attrs":{"ref":"r39"},"content":[{"type":"heading","attrs":{"ref":"r40","level":2},"content":[{"type":"text","text":"Step 5 / Connect the selector"}]},{"type":"paragraph","attrs":{"ref":"r41"},"content":[{"type":"text","text":"Identify the neck input, bridge input, output contacts and frame ground on the actual switch using its documentation and a continuity meter. Follow the generated diagram, including the joined output contacts where shown. Similar-looking switches may have different terminal arrangements."}]},{"type":"paragraph","attrs":{"ref":"r42"},"content":[{"type":"text","text":"If no new selector was ordered, reconnect the existing one to the required circuit destinations. Keep signal connections insulated from the switch frame and nearby shielding."}]}]},{"type":"container","attrs":{"ref":"r43"},"content":[{"type":"heading","attrs":{"ref":"r44","level":2},"content":[{"type":"text","text":"Step 6 / Connect the output jack"}]},{"type":"paragraph","attrs":{"ref":"r45"},"content":[{"type":"text","text":"Connect the output signal to Tip and common ground to Sleeve in the supported passive mono circuit. Use a known-good unplugged cable and continuity checks to identify the corresponding contacts. Some multi-contact jacks use several spring contacts for the same electrical node; follow the selected part’s documentation."}]},{"type":"paragraph","attrs":{"ref":"r46"},"content":[{"type":"text","text":"Secure the jack without allowing it to rotate and strain the wires. Check that an inserted plug does not touch a signal lug or trap a wire against shielding."}]}]},{"type":"container","attrs":{"ref":"r47"},"content":[{"type":"heading","attrs":{"ref":"r48","level":2},"content":[{"type":"text","text":"Step 7 / Grounding"}]},{"type":"paragraph","attrs":{"ref":"r49"},"content":[{"type":"text","text":"Retain the bridge/string ground and connect it to the common ground network shown. Confirm continuity between jack sleeve, specified pot casings, pickup shields, switch frame and bridge/string ground. Shielding, where fitted, must not touch hot terminals."}]},{"type":"paragraph","attrs":{"ref":"r50"},"content":[{"type":"text","text":"Do not remove a bridge ground simply to hide a noise problem, and do not modify amplifier mains wiring. Unexplained noise or an unfamiliar grounding arrangement warrants further diagnosis."}]}]},{"type":"container","attrs":{"ref":"r51"},"content":[{"type":"heading","attrs":{"ref":"r52","level":2},"content":[{"type":"text","text":"Step 8 / Inspect before testing"}]},{"type":"paragraph","attrs":{"ref":"r53"},"content":[{"type":"text","text":"Check each connection against the drawing. Look for loose or incompletely wetted solder joints, stray wire strands, bridges between adjacent lugs, melted insulation and unwanted contact with shielding. Check ground wires and every component terminal, including places hidden underneath the harness."}]},{"type":"paragraph","attrs":{"ref":"r54"},"content":[{"type":"text","text":"Let joints cool before moving them. A large solder blob does not guarantee a reliable connection. Resolve mechanical strain and exposed conductors before electrical testing."}]}]},{"type":"container","attrs":{"ref":"r55"},"content":[{"type":"heading","attrs":{"ref":"r56","level":2},"content":[{"type":"text","text":"Step 9 / Electrical test"}]},{"type":"paragraph","attrs":{"ref":"r57"},"content":[{"type":"text","text":"With the instrument disconnected from the amplifier, check intended ground continuity and selector operation. At full volume, check for an unintended near-zero resistance between jack tip and sleeve. A pickup circuit normally presents a finite DC resistance, while a volume at zero intentionally grounds the output; do not interpret every continuity beep as a fault."}]},{"type":"paragraph","attrs":{"ref":"r58"},"content":[{"type":"text","text":"Check the resistance changes as each volume is moved and compare selector readings logically. Capacitors do not pass steady DC, so a meter’s resistance or continuity setting cannot confirm a complete tone-control response. Check component values out of circuit where parallel paths would affect the reading."}]}]},{"type":"container","attrs":{"ref":"r59"},"content":[{"type":"heading","attrs":{"ref":"r60","level":2},"content":[{"type":"text","text":"Step 10 / Functional test"}]},{"type":"paragraph","attrs":{"ref":"r61"},"content":[{"type":"text","text":"After the basic checks pass, connect to a known-good amplifier at low volume. Confirm neck, bridge and both selector positions; check both volume and tone controls over their full travel. Check for intermittent connections as you gently operate controls, without pulling the wiring."}]},{"type":"paragraph","attrs":{"ref":"r62"},"content":[{"type":"text","text":"Play the guitar to assess any treble bleed as volume is reduced. Check additional switching only against its specific verified instructions. The standard Les Paul circuit mutes both pickups when either volume is at zero in the Both position; that is expected for this wiring."}]},{"type":"paragraph","attrs":{"ref":"r63"},"content":[{"type":"text","text":"Only refit covers once everything works, ensuring no wires or components are pinched. Retest after final assembly."}]},{"type":"protected","attrs":{"ref":"r64"}}]},{"type":"protected","attrs":{"ref":"r65"}}]}}}}'::jsonb,'{"template_key":"install","expected_intent":null,"refs":{"r1":{"kind":"node"},"r2":{"kind":"node"},"r3":{"kind":"node"},"r4":{"kind":"node"},"r5":{"kind":"node"},"r6":{"kind":"node"},"r7":{"kind":"node"},"r8":{"kind":"node"},"r9":{"kind":"node"},"r10":{"kind":"node"},"r11":{"kind":"node"},"r12":{"kind":"node"},"r13":{"kind":"node"},"r14":{"kind":"node"},"r15":{"kind":"node"},"r16":{"kind":"node"},"r17":{"kind":"node"},"r18":{"kind":"node"},"r19":{"kind":"node"},"r20":{"kind":"protected"},"r21":{"kind":"node"},"r22":{"kind":"node"},"r23":{"kind":"node"},"r24":{"kind":"node"},"r25":{"kind":"node"},"r26":{"kind":"node"},"r27":{"kind":"node"},"r28":{"kind":"node"},"r29":{"kind":"node"},"r30":{"kind":"node"},"r31":{"kind":"node"},"r32":{"kind":"node"},"r33":{"kind":"node"},"r34":{"kind":"node"},"r35":{"kind":"node"},"r36":{"kind":"node"},"r37":{"kind":"node"},"r38":{"kind":"node"},"r39":{"kind":"node"},"r40":{"kind":"node"},"r41":{"kind":"node"},"r42":{"kind":"node"},"r43":{"kind":"node"},"r44":{"kind":"node"},"r45":{"kind":"node"},"r46":{"kind":"node"},"r47":{"kind":"node"},"r48":{"kind":"node"},"r49":{"kind":"node"},"r50":{"kind":"node"},"r51":{"kind":"node"},"r52":{"kind":"node"},"r53":{"kind":"node"},"r54":{"kind":"node"},"r55":{"kind":"node"},"r56":{"kind":"node"},"r57":{"kind":"node"},"r58":{"kind":"node"},"r59":{"kind":"node"},"r60":{"kind":"node"},"r61":{"kind":"node"},"r62":{"kind":"node"},"r63":{"kind":"node"},"r64":{"kind":"protected"},"r65":{"kind":"protected"}},"slots":["main"]}'::jsonb),
('b1aa1591-8878-5d36-af12-fa262c3a2e13','troubleshoot','{"version":1,"title":"Passive guitar troubleshooting","slug":"troubleshooting","category":"troubleshooting","intro":"Start with a symptom, narrow the checks, and inspect the appropriate circuit view.","seo_title":"Passive guitar troubleshooting","meta_description":"Start with a symptom, narrow the checks, and inspect the appropriate circuit view.","indexable":true,"primary_intent":null,"related":["pots","lugs","grounding-guide"],"tools":["signal"],"components":[],"published_at":null,"content_updated_at":null,"body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"paragraph","attrs":{"ref":"r1"},"content":[{"type":"text","text":"Symptoms suggest areas to inspect; they do not prove a diagnosis. Disconnect the guitar before continuity tests. Keep amplifier checks external; never work on mains-powered amplifier internals."}]},{"type":"container","attrs":{"ref":"r2"},"content":[{"type":"heading","attrs":{"ref":"r3","level":2},"content":[{"type":"text","text":"No output"}]},{"type":"heading","attrs":{"ref":"r4","level":3},"content":[{"type":"text","text":"Likely areas and safe basic checks"}]},{"type":"paragraph","attrs":{"ref":"r5"},"content":[{"type":"text","text":"Check the cable and amplifier input with a known working guitar first, then jack tip/sleeve wiring, unwanted hot-to-ground shorts and selector output."}]},{"type":"paragraph","attrs":{"ref":"r6"},"content":[{"type":"text","text":"Learn: Ground, shield and the output jack →","marks":[{"type":"link","attrs":{"href":"/luthier-hub/grounding-output/"}}]},{"type":"text","text":" · "},{"type":"text","text":"Inspect: Wiring Generator →","marks":[{"type":"link","attrs":{"href":"/wiring-generator/?g=%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22none%22%2C%22neckCap%22%3A%220.022%22%2C%22bridgeCap%22%3A%220.022%22%2C%22colours%22%3A%22generic%22%2C%22position%22%3A%22neck%22%2C%22shielding%22%3A%22yes%22%2C%22pickupProfiles%22%3A%7B%22neck%22%3A%22generic%22%2C%22bridge%22%3A%22generic%22%7D%7D&sf=%7B%22version%22%3A1%2C%22configuration%22%3A%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22none%22%2C%22neckCap%22%3A%220.022%22%2C%22bridgeCap%22%3A%220.022%22%2C%22colours%22%3A%22generic%22%2C%22position%22%3A%22neck%22%2C%22shielding%22%3A%22yes%22%2C%22pickupProfiles%22%3A%7B%22neck%22%3A%22generic%22%2C%22bridge%22%3A%22generic%22%7D%7D%2C%22controlPositions%22%3A%7B%22neck%22%3A%7B%22volume%22%3A7%2C%22tone%22%3A10%7D%2C%22bridge%22%3A%7B%22volume%22%3A7%2C%22tone%22%3A10%7D%7D%2C%22responseAssumptions%22%3A%7B%22channels%22%3A%7B%22neck%22%3A%7B%22pickup%22%3A%22generic%22%2C%22volumePot%22%3A500%2C%22tonePot%22%3A500%7D%2C%22bridge%22%3A%7B%22pickup%22%3A%22generic%22%2C%22volumePot%22%3A500%2C%22tonePot%22%3A500%7D%7D%2C%22cableC%22%3A500%2C%22loadR%22%3A1%7D%7D"}}]}]}]},{"type":"container","attrs":{"ref":"r7"},"content":[{"type":"heading","attrs":{"ref":"r8","level":2},"content":[{"type":"text","text":"One pickup does not work"}]},{"type":"heading","attrs":{"ref":"r9","level":3},"content":[{"type":"text","text":"Likely areas and safe basic checks"}]},{"type":"paragraph","attrs":{"ref":"r10"},"content":[{"type":"text","text":"Compare both single-pickup positions. Inspect its hot lead, return, series link and selector branch against the diagram."}]},{"type":"paragraph","attrs":{"ref":"r11"},"content":[{"type":"text","text":"Learn: Pickup conductors and colour conventions →","marks":[{"type":"link","attrs":{"href":"/luthier-hub/pickup-conductors/"}}]},{"type":"text","text":" · "},{"type":"text","text":"Inspect: Signal Forge / Circuit Lab →","marks":[{"type":"link","attrs":{"href":"/circuit-forge/?sf=%7B%22version%22%3A1%2C%22configuration%22%3A%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22none%22%2C%22neckCap%22%3A%220.022%22%2C%22bridgeCap%22%3A%220.022%22%2C%22colours%22%3A%22generic%22%2C%22position%22%3A%22neck%22%2C%22shielding%22%3A%22yes%22%2C%22pickupProfiles%22%3A%7B%22neck%22%3A%22generic%22%2C%22bridge%22%3A%22generic%22%7D%7D%2C%22controlPositions%22%3A%7B%22neck%22%3A%7B%22volume%22%3A7%2C%22tone%22%3A10%7D%2C%22bridge%22%3A%7B%22volume%22%3A7%2C%22tone%22%3A10%7D%7D%2C%22responseAssumptions%22%3A%7B%22channels%22%3A%7B%22neck%22%3A%7B%22pickup%22%3A%22generic%22%2C%22volumePot%22%3A500%2C%22tonePot%22%3A500%7D%2C%22bridge%22%3A%7B%22pickup%22%3A%22generic%22%2C%22volumePot%22%3A500%2C%22tonePot%22%3A500%7D%7D%2C%22cableC%22%3A500%2C%22loadR%22%3A1%7D%7D&mode=physical"}}]}]}]},{"type":"container","attrs":{"ref":"r12"},"content":[{"type":"heading","attrs":{"ref":"r13","level":2},"content":[{"type":"text","text":"Volume does not fully mute"}]},{"type":"heading","attrs":{"ref":"r14","level":3},"content":[{"type":"text","text":"Likely areas and safe basic checks"}]},{"type":"paragraph","attrs":{"ref":"r15"},"content":[{"type":"text","text":"Check the ground-end lug bond and the input/wiper identification against the selected wiring. Do not assume every two-volume topology behaves identically."}]},{"type":"paragraph","attrs":{"ref":"r16"},"content":[{"type":"text","text":"Learn: Potentiometers explained →","marks":[{"type":"link","attrs":{"href":"/luthier-hub/potentiometers-explained/"}}]},{"type":"text","text":" · "},{"type":"text","text":"Inspect: Wiring Generator →","marks":[{"type":"link","attrs":{"href":"/wiring-generator/?g=%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22none%22%2C%22neckCap%22%3A%220.022%22%2C%22bridgeCap%22%3A%220.022%22%2C%22colours%22%3A%22generic%22%2C%22position%22%3A%22neck%22%2C%22shielding%22%3A%22yes%22%2C%22pickupProfiles%22%3A%7B%22neck%22%3A%22generic%22%2C%22bridge%22%3A%22generic%22%7D%7D&sf=%7B%22version%22%3A1%2C%22configuration%22%3A%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22none%22%2C%22neckCap%22%3A%220.022%22%2C%22bridgeCap%22%3A%220.022%22%2C%22colours%22%3A%22generic%22%2C%22position%22%3A%22neck%22%2C%22shielding%22%3A%22yes%22%2C%22pickupProfiles%22%3A%7B%22neck%22%3A%22generic%22%2C%22bridge%22%3A%22generic%22%7D%7D%2C%22controlPositions%22%3A%7B%22neck%22%3A%7B%22volume%22%3A7%2C%22tone%22%3A10%7D%2C%22bridge%22%3A%7B%22volume%22%3A7%2C%22tone%22%3A10%7D%7D%2C%22responseAssumptions%22%3A%7B%22channels%22%3A%7B%22neck%22%3A%7B%22pickup%22%3A%22generic%22%2C%22volumePot%22%3A500%2C%22tonePot%22%3A500%7D%2C%22bridge%22%3A%7B%22pickup%22%3A%22generic%22%2C%22volumePot%22%3A500%2C%22tonePot%22%3A500%7D%7D%2C%22cableC%22%3A500%2C%22loadR%22%3A1%7D%7D"}}]}]}]},{"type":"container","attrs":{"ref":"r17"},"content":[{"type":"heading","attrs":{"ref":"r18","level":2},"content":[{"type":"text","text":"Tone control does nothing"}]},{"type":"heading","attrs":{"ref":"r19","level":3},"content":[{"type":"text","text":"Likely areas and safe basic checks"}]},{"type":"paragraph","attrs":{"ref":"r20"},"content":[{"type":"text","text":"Inspect the capacitor connection, tone wiper and required ground bond. Check the selected wiring style before moving a lead."}]},{"type":"paragraph","attrs":{"ref":"r21"},"content":[{"type":"text","text":"Learn: Capacitors and treble bleeds explained →","marks":[{"type":"link","attrs":{"href":"/luthier-hub/capacitors-treble-bleeds/"}}]},{"type":"text","text":" · "},{"type":"text","text":"Inspect: Signal Forge / Signal Lab →","marks":[{"type":"link","attrs":{"href":"/circuit-forge/?sf=%7B%22version%22%3A1%2C%22configuration%22%3A%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22none%22%2C%22neckCap%22%3A%220.022%22%2C%22bridgeCap%22%3A%220.022%22%2C%22colours%22%3A%22generic%22%2C%22position%22%3A%22neck%22%2C%22shielding%22%3A%22yes%22%2C%22pickupProfiles%22%3A%7B%22neck%22%3A%22generic%22%2C%22bridge%22%3A%22generic%22%7D%7D%2C%22controlPositions%22%3A%7B%22neck%22%3A%7B%22volume%22%3A7%2C%22tone%22%3A10%7D%2C%22bridge%22%3A%7B%22volume%22%3A7%2C%22tone%22%3A10%7D%7D%2C%22responseAssumptions%22%3A%7B%22channels%22%3A%7B%22neck%22%3A%7B%22pickup%22%3A%22generic%22%2C%22volumePot%22%3A500%2C%22tonePot%22%3A500%7D%2C%22bridge%22%3A%7B%22pickup%22%3A%22generic%22%2C%22volumePot%22%3A500%2C%22tonePot%22%3A500%7D%7D%2C%22cableC%22%3A500%2C%22loadR%22%3A1%7D%7D&mode=signal"}}]}]}]},{"type":"container","attrs":{"ref":"r22"},"content":[{"type":"heading","attrs":{"ref":"r23","level":2},"content":[{"type":"text","text":"Hum changes when touching strings"}]},{"type":"heading","attrs":{"ref":"r24","level":3},"content":[{"type":"text","text":"Likely areas and safe basic checks"}]},{"type":"paragraph","attrs":{"ref":"r25"},"content":[{"type":"text","text":"Inspect bridge/string ground and shielding continuity. This symptom can be consistent with interference pickup but is not proof of a specific fault."}]},{"type":"paragraph","attrs":{"ref":"r26"},"content":[{"type":"text","text":"Learn: Ground, shield and the output jack →","marks":[{"type":"link","attrs":{"href":"/luthier-hub/grounding-output/"}}]},{"type":"text","text":" · "},{"type":"text","text":"Inspect: Wiring Generator →","marks":[{"type":"link","attrs":{"href":"/wiring-generator/?g=%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22none%22%2C%22neckCap%22%3A%220.022%22%2C%22bridgeCap%22%3A%220.022%22%2C%22colours%22%3A%22generic%22%2C%22position%22%3A%22neck%22%2C%22shielding%22%3A%22yes%22%2C%22pickupProfiles%22%3A%7B%22neck%22%3A%22generic%22%2C%22bridge%22%3A%22generic%22%7D%7D&sf=%7B%22version%22%3A1%2C%22configuration%22%3A%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22none%22%2C%22neckCap%22%3A%220.022%22%2C%22bridgeCap%22%3A%220.022%22%2C%22colours%22%3A%22generic%22%2C%22position%22%3A%22neck%22%2C%22shielding%22%3A%22yes%22%2C%22pickupProfiles%22%3A%7B%22neck%22%3A%22generic%22%2C%22bridge%22%3A%22generic%22%7D%7D%2C%22controlPositions%22%3A%7B%22neck%22%3A%7B%22volume%22%3A7%2C%22tone%22%3A10%7D%2C%22bridge%22%3A%7B%22volume%22%3A7%2C%22tone%22%3A10%7D%7D%2C%22responseAssumptions%22%3A%7B%22channels%22%3A%7B%22neck%22%3A%7B%22pickup%22%3A%22generic%22%2C%22volumePot%22%3A500%2C%22tonePot%22%3A500%7D%2C%22bridge%22%3A%7B%22pickup%22%3A%22generic%22%2C%22volumePot%22%3A500%2C%22tonePot%22%3A500%7D%7D%2C%22cableC%22%3A500%2C%22loadR%22%3A1%7D%7D"}}]}]}]},{"type":"container","attrs":{"ref":"r27"},"content":[{"type":"heading","attrs":{"ref":"r28","level":2},"content":[{"type":"text","text":"Hum does not change when touching strings"}]},{"type":"heading","attrs":{"ref":"r29","level":3},"content":[{"type":"text","text":"Likely areas and safe basic checks"}]},{"type":"paragraph","attrs":{"ref":"r30"},"content":[{"type":"text","text":"Try another cable and environment, then inspect shielding, return paths and pickup type. Single-coil interference is not always a wiring defect."}]},{"type":"paragraph","attrs":{"ref":"r31"},"content":[{"type":"text","text":"Learn: Ground, shield and the output jack →","marks":[{"type":"link","attrs":{"href":"/luthier-hub/grounding-output/"}}]},{"type":"text","text":" · "},{"type":"text","text":"Inspect: Wiring Generator →","marks":[{"type":"link","attrs":{"href":"/wiring-generator/?g=%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22none%22%2C%22neckCap%22%3A%220.022%22%2C%22bridgeCap%22%3A%220.022%22%2C%22colours%22%3A%22generic%22%2C%22position%22%3A%22neck%22%2C%22shielding%22%3A%22yes%22%2C%22pickupProfiles%22%3A%7B%22neck%22%3A%22generic%22%2C%22bridge%22%3A%22generic%22%7D%7D&sf=%7B%22version%22%3A1%2C%22configuration%22%3A%7B%22guitar%22%3A%22les-paul%22%2C%22wiring%22%3A%22modern%22%2C%22bleed%22%3A%22none%22%2C%22neckCap%22%3A%220.022%22%2C%22bridgeCap%22%3A%220.022%22%2C%22colours%22%3A%22generic%22%2C%22position%22%3A%22neck%22%2C%22shielding%22%3A%22yes%22%2C%22pickupProfiles%22%3A%7B%22neck%22%3A%22generic%22%2C%22bridge%22%3A%22generic%22%7D%7D%2C%22controlPositions%22%3A%7B%22neck%22%3A%7B%22